'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EN={menu:'Menu',secret:'Secret · VIP',videos:'Videos',home:'Home',catalog:'Manhwa',updates:'New chapters',saved:'My library',login:'Sign in',tag:'YOUR NEXT WORLD',hero:'Beyond the neon,<br><em>a new story awaits.</em>',desc:'A little escape from the everyday. Discover original stories, one chapter at a time, in Mongolian and English.',read:'Start reading',more:'Explore stories',popular:'Discover your next story',sub:'New worlds. Unforgettable characters.',all:'View all',continue:'A story worth coming back to',contdesc:'Your place is saved automatically on this device.',resume:'Continue reading',latest:'Latest chapters',latestsub:'A new chapter, a new adventure.',top:'Editor’s picks',empty:'No stories found.',catalogtitle:'Find your next world',savedtitle:'Your library',savedsub:'The stories you save are kept on this device.',search:'Search stories…',demo:'ORIGINAL DEMO',chapter:'Chapter',back:'Back',details:'Story details',save:'Save',savedbtn:'Saved',allgenres:'All',fantasy:'Fantasy',action:'Action',romance:'Romance',adventure:'Adventure',scifi:'Sci-fi'};
let lang=localStorage.getItem('mur-lang')||'mn';
const MN={menu:'Цэс',secret:'Secret · VIP',videos:'Видео',home:'Нүүр',catalog:'Манхва',updates:'Шинэ бүлэг',saved:'Миний сан',login:'Нэвтрэх',tag:'ТАНЫ ДАРААГИЙН ЕРТӨНЦ',hero:'Өөр ертөнц.<br><em>Өөрийн хэмнэлээр.</em>',desc:'Өдөр тутмаас түрхэн холд. Шинэ түүх, мартагдашгүй дүрүүдийг Монгол, Англи хэлээр нээгээрэй.',read:'Уншиж эхлэх',more:'Манхва нээх',popular:'Дараагийн дуртай түүхээ ол',sub:'Шинэ ертөнц. Мартагдашгүй дүрүүд.',all:'Бүгдийг харах',continue:'Түүх чинь чамайг хүлээж байна',contdesc:'Уншсан хэсгийг энэ төхөөрөмж дээр автоматаар хадгална.',resume:'Үргэлжлүүлэн унших',latest:'Шинэ бүлгүүд',latestsub:'Шинэ бүлэг бүр — шинэ адал явдал.',top:'Редакторын сонголт',empty:'Тохирох бүтээл олдсонгүй.',catalogtitle:'Шинэ ертөнцөө нээгээрэй',savedtitle:'Миний сан',savedsub:'Хадгалсан бүтээлүүд энэ төхөөрөмж дээр үлдэнэ.',search:'Нэрээр хайх…',demo:'ЖИШЭЭ БҮТЭЭЛ',chapter:'Бүлэг',back:'Буцах',details:'Дэлгэрэнгүй',save:'Хадгалах',savedbtn:'Хадгалсан',allgenres:'Бүгд',fantasy:'Фантази',action:'Тулаан',romance:'Романс',adventure:'Адал явдал',scifi:'Шинжлэх ухаан'};
const t=k=>(lang==='en'?EN:MN)[k]||k;
const originals=[['Неон хотын сүүлчийн мөр','The Last Trace','fantasy','action','NEON\nTRACE'],['Сарны хаалганы цаана','Beyond the Moon Gate','fantasy','adventure','MOON\nGATE'],['Чамд үлдээсэн захидал','A Letter for You','romance','fantasy','DEAR\nTOMORROW'],['Мартагдсан ойн нууц','The Forgotten Forest','adventure','fantasy','THE LOST\nFOREST'],['Оддын хооронд','Between the Stars','scifi','romance','BETWEEN\nSTARS'],['Үүрийн харуул','The Dawn Keeper','action','adventure','DAWN\nKEEPER']];
const initial=()=>({series:originals.map((a,i)=>({id:'demo-'+i,mn:a[0],en:a[1],genres:[a[2],a[3]],cover:'art/cover-'+i+'.svg',title:a[4],demo:true,description:'Sakitoru платформд зориулан бүтээсэн богино жишээ түүх. Неон гэрэлт хотын нэгэн шөнө залуу аялагч мартагдсан амлалтыг эрж олно. Энд ашигласан зураг, өгүүлэмж нь платформын үйлдлийг турших зориулалттай эх бүтээл юм.',descriptionEn:'An original short demonstration created for SAKITORU. On a neon-lit night, a young traveler searches for a forgotten promise. Original illustrations and writing demonstrate the reading experience.',chapters:[{id:'chapter-'+i,name:'Эхлэл',nameEn:'The Beginning',pages:[0,1,2].map(n=>({url:'art/page-'+n+'.png',mn:['Хот амлалт бүрийг санаж байлаа.','Хаалганы цаана гэрэл сүүмэлзэнэ.','Энэ бол зөвхөн эхлэл байв.'][n],en:['The city remembered every promise.','A light flickered beyond the gate.','This was only the beginning.'][n]}))}]})),saved:[],history:null});
let state=initial(), db, filter='all', search='', sort='default', initialized=false;
const uid=()=>crypto.randomUUID();
async function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('mur-beta',1);q.onupgradeneeded=()=>q.result.createObjectStore('app');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function persist(next){if(window.MUR_CLOUDFLARE&&(!sameContent(next.series,state.series)||!sameContent(next.videos,state.videos))){await publishCloudContent(next);}if((!sameContent(next.series,state.series)||!sameContent(next.videos,state.videos))&&!canManage())throw Error('Зөвхөн сайтын эзэмшигч бүтээл, бүлэг, зураг өөрчлөх эрхтэй.');if(!db)throw Error('Төхөөрөмжийн хадгалалт боломжгүй байна.');await new Promise((resolve,reject)=>{const tx=db.transaction('app','readwrite');tx.objectStore('app').put(window.MUR_CLOUDFLARE?{...next,series:next.series.filter(s=>!s.mature)}:next,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next;undoSnapshot=null;restoreUndo=null}
const clone=()=>structuredClone(state);
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){$('#modal-body').innerHTML=html;const heading=$('#modal-body h2');if(heading)$('#modal').setAttribute('aria-label',heading.textContent);if(!$('#modal').open)$('#modal').showModal()}
function title(s){return lang==='en'?(s.en||s.mn):s.mn}
function pages(s,c){return(s.chapters.find(x=>x.id===c)||s.chapters[0])}
function card(s){return `<article class="card"><a href="#story/${s.id}" class="cover"><img src="${esc(s.cover)}" alt="${esc(title(s))}" loading="lazy"><span class="cover-label ${s.demo?'':'new'}">${s.mature?'VIP · 18+':s.demo?t('demo'):'ШИНЭ'}</span>${s.demo?`<span class="cover-title">${esc(s.title)}</span><span class="cover-credit">SAKITORU ORIGINAL</span>`:''}<span class="cover-score">${s.demo?'✦ ORIGINAL':'✦ '+t(s.genres[0])}</span></a><button class="bookmark ${state.saved.includes(s.id)?'saved':''}" data-save="${s.id}" aria-label="${esc(t('save')+' '+title(s))}" aria-pressed="${state.saved.includes(s.id)}">♧</button><h3><a href="#story/${s.id}">${esc(title(s))}</a></h3><p>${s.genres.map(g=>t(g)).join(' · ')}<span>${s.chapters.length} ${t('chapter').toLowerCase()}</span></p></article>`}
function filterbar(){return `<div class="filters">${['all','fantasy','action','romance','adventure','scifi'].map(g=>`<button class="chip ${filter===g?'selected':''}" data-filter="${g}">${g==='all'?t('allgenres'):t(g)}</button>`).join('')}</div>`}
function filtered(list){const result=list.filter(s=>(!s.mature||(location.hash==='#secret'&&ageConfirmed()))&&(filter==='all'||s.genres.includes(filter))&&(!search||`${s.mn} ${s.en}`.toLowerCase().includes(search.toLowerCase())));return sort==='az'?result.sort((a,b)=>title(a).localeCompare(title(b),lang==='mn'?'mn':'en')):sort==='chapters'?result.sort((a,b)=>b.chapters.length-a.chapters.length):result}
function grid(list){return list.length?list.map(card).join(''):`<div class="empty">${t('empty')}</div>`}
function sectionHead(h,sub,link){return `<div class="section-head"><div><h2>${h}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${t('all')} <span>↗</span></a>`:''}</div>`}
function updates(list=state.series){return list.filter(s=>!s.mature).flatMap(s=>s.chapters.map((c,i)=>({s,c,i}))).reverse().slice(0,6).map(({s,c,i})=>`<a class="update-item" href="#read/${s.id}/${c.id}"><img src="${esc(s.cover)}" alt="" loading="lazy"><div><h3>${esc(title(s))}</h3><p>${t('chapter')} ${i+1} · ${esc(lang==='en'?(c.nameEn||c.name):c.name)}</p></div><small>${s.demo?t('demo'):'ШИНЭ'}</small></a>`).join('')||`<p class="tiny">Бүлэг оруулаагүй байна.</p>`}
function home(){const hero=state.series.find(s=>s.id==='demo-0'&&!s.mature)||state.series.find(s=>!s.mature);if(!hero)return catalog();const first=hero.chapters[0];return `<section class="hero"><img class="hero-art" src="art/scene-0.svg" alt="Неон гэрэлт хотод илд барьсан аялагч"><div class="hero-content"><div class="eyebrow">${t('tag')}</div><h1>${t('hero')}</h1><p class="hero-description">${t('desc')}</p><div class="hero-meta"><span class="rating">✦ SAKITORU ORIGINAL</span><span>·</span><span>MN / EN</span><span class="tag">${t('fantasy')}</span></div><div class="hero-buttons">${first?`<a class="btn" href="#read/${hero.id}/${first.id}">▷ ${t('read')} <span>→</span></a>`:''}<a class="btn secondary" href="#catalog">${t('more')} ↗</a></div><div class="hero-bottom"><span class="bar"></span><span class="bar off"></span><span class="bar off"></span><span style="margin-left:9px"><b>01</b> / ORIGINAL COLLECTION</span></div></div><div class="hero-sticker"><span>✧</span><div>${lang==='en'?'One story. Two languages.':'Нэг түүх. Хоёр хэл.'}<small>${lang==='en'?'Read in Mongolian & English':'Монгол, Англи хэлээр уншаарай'}</small></div></div></section><div class="container">${discoveryLinks()}<section class="section">${sectionHead(t('popular'),t('sub'),'#catalog')}${filterbar()}<div class="cards" id="cards">${grid(filtered(state.series).slice(0,6))}</div></section>${continueBand(hero)}<div class="lower-grid"><section>${sectionHead(t('latest'),t('latestsub'),'#updates')}<div class="update-list">${updates()}</div></section><aside class="ranking">${sectionHead(t('top'),'SAKITORU ORIGINALS',null)}${state.series.filter(s=>!s.mature).slice(0,3).map((s,i)=>`<a href="#story/${s.id}" class="ranking-row"><span class="rank">0${i+1}</span><div><h3>${esc(title(s))}</h3><p>${s.genres.map(g=>t(g)).join(' · ')}</p></div><small>↗</small></a>`).join('')}</aside></div></div>`}
function catalog(saved=false,mature=false){return `<div class="container page-bottom"><div class="page-title"><div class="eyebrow">${mature?'Sakitoru • AFTER HOURS':saved?'YOUR COLLECTION':'EXPLORE THE STORIES'}</div><h1>${mature?(lang==='en'?'Secret · VIP':'Secret · VIP'):saved?t('savedtitle'):t('catalogtitle')}</h1><p>${mature?(lang==='en'?'18+ stories for VIP members.':'18 нас хүрсэн VIP гишүүдэд зориулсан бүтээлүүд.'):saved?t('savedsub'):t('sub')}</p></div><div class="catalog-tools"><div class="searchbox"><span aria-hidden="true">⌕</span><input id="search" type="search" value="${esc(search)}" placeholder="${t('search')}" aria-label="${t('search')}"></div><label class="sort-label">${lang==='en'?'Sort':'Эрэмбэ'} <select id="catalog-sort"><option value="default" ${sort==='default'?'selected':''}>${lang==='en'?'Featured':'Онцлох'}</option><option value="az" ${sort==='az'?'selected':''}>${lang==='en'?'Title A–Z':'Нэрээр А–Я'}</option><option value="chapters" ${sort==='chapters'?'selected':''}>${lang==='en'?'Most chapters':'Олон бүлэгтэй'}</option></select></label></div><p class="result-count" id="result-count">${filtered(catalogList(saved,mature)).length} ${lang==='en'?'stories':'бүтээл'}</p>${filterbar()}<div class="cards" id="cards">${grid(filtered(catalogList(saved,mature)))}</div></div>`}
let chapterQuery='', chapterFilter='all', chapterOrder='new', detailStory='';
function chapterDone(s,c){const p=progressFor(s.id,c.id);return !!p.completed}
function story(id){
 const s=state.series.find(x=>x.id===id);if(!s)return missing();
 if(detailStory!==id){detailStory=id;chapterQuery='';chapterFilter='all';chapterOrder='new'}
 const en=lang==='en',done=s.chapters.filter(c=>chapterDone(s,c)).length;
 const last=state.history?.series===id?s.chapters.find(c=>c.id===state.history.chapter):null;
 const first=s.chapters[0],resume=last||first,percent=s.chapters.length?Math.round(done/s.chapters.length*100):0;
 const related=state.series.filter(x=>!x.mature&&x.id!==id&&x.genres.some(g=>s.genres.includes(g))).slice(0,4);
 return `<div class="story-page"><section class="story-hero"><img class="story-backdrop" src="${esc(s.cover)}" alt=""><div class="story-shade"></div><div class="container story-hero-inner"><a class="story-breadcrumb" href="#catalog">← ${t('catalog')} <span>/ ${esc(title(s))}</span></a><div class="story-overview"><div class="story-poster"><img src="${esc(s.cover)}" alt="${esc(title(s))}"><span>${s.demo?'SAKITORU ORIGINAL':'MN / EN'}</span></div><div class="story-intro"><div class="eyebrow">Sakitoru SERIES <span>• ${s.mature?'VIP · 18+':en?'FREE TO READ':'ҮНЭГҮЙ УНШИХ'}</span></div><h1>${esc(title(s))}</h1><div class="story-facts"><span>${s.chapters.length} ${t('chapter').toLowerCase()}</span><span>MN / EN</span><span>${s.demo?t('demo'):(en?'Community story':'Бүтээл')}</span></div><div class="story-genres">${s.genres.map(g=>`<span class="tag">${t(g)}</span>`).join('')}</div><p class="story-summary">${esc(en?(s.descriptionEn||s.description):s.description)}</p><div class="story-actions">${resume?`<a class="btn" href="#read/${s.id}/${resume.id}">▷ ${last?t('resume'):t('read')} <span>→</span></a>`:''}<button class="btn secondary" data-save="${s.id}" aria-pressed="${state.saved.includes(id)}">${state.saved.includes(id)?'♥ '+t('savedbtn'):'♡ '+t('save')}</button></div>${last?`<a class="story-start-over" href="#read/${id}/${first.id}">${en?'Read from chapter 1':'Эхний бүлгээс унших'} ↗</a>`:''}</div></div></div></section><div class="container story-body"><section class="story-progress"><div class="progress-icon">▤</div><div><h2>${en?'Your reading journey':'Таны уншсан явц'}</h2><p>${done} / ${s.chapters.length} ${en?'chapters finished':'бүлгийг дуустал үзсэн'} · ${en?'Saved on this device':'Энэ төхөөрөмж дээр хадгална'}</p><div class="story-progress-track"><span style="width:${percent}%"></span></div></div><strong>${percent}<small>%</small></strong></section><div class="story-columns"><section class="story-chapters" aria-labelledby="chapter-heading"><div class="chapter-heading"><h2 id="chapter-heading">${en?'Chapters':'Бүлгүүд'} <span>${s.chapters.length}</span></h2><label class="chapter-order-label"><span class="sr-only">${en?'Chapter order':'Бүлгийн дараалал'}</span><select id="chapter-order"><option value="new" ${chapterOrder==='new'?'selected':''}>${en?'Newest first':'Шинэ нь эхэндээ'}</option><option value="old" ${chapterOrder==='old'?'selected':''}>${en?'Oldest first':'Эхнээс нь'}</option></select></label></div><label class="chapter-search"><span aria-hidden="true">⌕</span><input id="chapter-search" type="search" value="${esc(chapterQuery)}" placeholder="${en?'Search chapter number or name…':'Бүлгийн дугаар эсвэл нэрээр хайх…'}" aria-label="${en?'Search chapters':'Бүлэг хайх'}"></label><div class="chapter-filters">${[['all',en?'All':'Бүгд',s.chapters.length],['unread',en?'Unfinished':'Дуусаагүй',s.chapters.length-done],['read',en?'Finished':'Дууссан',done]].map(([key,label,count])=>`<button class="chip ${chapterFilter===key?'selected':''}" data-chapter-filter="${key}" aria-pressed="${chapterFilter===key}">${label} <span>${count}</span></button>`).join('')}</div><p id="chapter-results" class="tiny" aria-live="polite"></p><div id="story-chapter-list" class="chapter-list">${storyChapterRows(s)}</div></section><aside class="story-aside"><div class="eyebrow">${en?'ABOUT THIS STORY':'БҮТЭЭЛИЙН ТУХАЙ'}</div><h3>${en?'A new world, at your pace.':'Өөр ертөнц. Өөрийн хэмнэлээр.'}</h3><dl><div><dt>${en?'Languages':'Хэл'}</dt><dd>Монгол / English</dd></div><div><dt>${en?'Access':'Унших эрх'}</dt><dd>${s.mature?'VIP':en?'Free':'Үнэгүй'}</dd></div><div><dt>${en?'Collection':'Ангилал'}</dt><dd>${s.demo?'SAKITORU Original':t(s.genres[0])}</dd></div></dl><p>${en?'Tap an image in the reader to switch its translation.':'Уншигчийн зураг дээр товшоод Монгол, Англи текстийг сэлгээрэй.'}</p></aside></div>${related.length?`<section class="story-related">${sectionHead(en?'Your next story':'Дараагийн унших түүх',en?'More worlds to discover':'Шинэ ертөнцүүд таныг хүлээж байна','#catalog')}<div class="cards">${related.map(card).join('')}</div></section>`:''}</div></div>`
}
function storyChapterRows(s){
 const en=lang==='en',q=chapterQuery.trim().toLocaleLowerCase();
 let rows=s.chapters.map((c,i)=>({c,i,done:chapterDone(s,c)})).filter(({c,i,done})=>(chapterFilter==='all'||(chapterFilter==='read'?done:!done))&&(!q||`${i+1} ${c.name} ${c.nameEn||''}`.toLocaleLowerCase().includes(q)));
 if(chapterOrder==='new')rows.reverse();
 return rows.map(({c,i,done})=>`<a class="chapter-row story-chapter-row ${done?'chapter-finished':''}" href="#read/${s.id}/${c.id}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><span class="chapter-name"><strong>${esc(en?(c.nameEn||c.name):c.name)}</strong><small>${t('chapter')} ${i+1} · ${c.pages.length} ${en?'pages':'зураг'}</small></span><span class="chapter-state">${done?'✓ '+(en?'Finished':'Дууссан'):(s.mature?'VIP':en?'Free':'Үнэгүй')}</span><span aria-hidden="true">↗</span></a>`).join('')||`<div class="empty">${en?'No matching chapters.':'Тохирох бүлэг олдсонгүй.'}</div>`
}
function refreshStoryChapters(){const s=state.series.find(x=>x.id===detailStory);if(!s||!$('#story-chapter-list'))return;$('#story-chapter-list').innerHTML=storyChapterRows(s);const n=$('#story-chapter-list').querySelectorAll('a').length;$('#chapter-results').textContent=`${n} ${lang==='en'?'chapters shown':'бүлэг харагдаж байна'}`;document.querySelectorAll('[data-chapter-filter]').forEach(b=>{const active=b.dataset.chapterFilter===chapterFilter;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))})}
document.addEventListener('input',e=>{if(e.target.id==='chapter-search'){chapterQuery=e.target.value;refreshStoryChapters()}});
document.addEventListener('change',e=>{if(e.target.id==='chapter-order'){chapterOrder=e.target.value;refreshStoryChapters()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-chapter-filter]');if(b){chapterFilter=b.dataset.chapterFilter;refreshStoryChapters()}});

function missing(){return `<div class="container page-bottom"><div class="empty">Бүтээл эсвэл бүлэг олдсонгүй.<br><br><a class="btn" href="#catalog">Манхва нээх →</a></div></div>`}
function reader(id,chapterId){const s=state.series.find(x=>x.id===id),c=s?.chapters.find(x=>x.id===chapterId);if(!s||!c)return missing();const i=s.chapters.indexOf(c);return `<div class="reader-toolbar"><a href="#story/${s.id}">← ${t('back')}</a><span class="reader-title">${esc(title(s))} · ${t('chapter')} ${i+1}</span><div><button data-readlang="mn" class="chip ${lang==='mn'?'selected':''}">Монгол</button> <button data-readlang="en" class="chip ${lang==='en'?'selected':''}">English</button></div></div><div class="reader-settings"><label>${lang==='en'?'Chapter':'Бүлэг'}<select id="reader-chapter">${s.chapters.map((ch,n)=>`<option value="${ch.id}" ${ch.id===c.id?'selected':''}>${n+1}. ${esc(lang==='en'?(ch.nameEn||ch.name):ch.name)}</option>`).join('')}</select></label><button id="focus-mode" class="chip" aria-pressed="${readerPrefs.focus}">⛶ ${lang==='en'?'Focus':'Төвлөрөх'}</button><button id="reader-width" class="chip" aria-pressed="${readerPrefs.narrow}">↔ ${lang==='en'?'Width':'Өргөн'}</button><button id="reader-text" class="chip" aria-pressed="${!readerPrefs.hideText}">Aa ${lang==='en'?'Translation':'Орчуулга'}</button></div><article class="reader">${s.demo?`<div class="notice">${lang==='en'?'Original demo · Tap each image to switch its translation.':'Жишээ эх бүтээл · Зураг дээр дарж орчуулгын хэлийг сольж болно.'}</div>`:''}${c.pages.length?c.pages.map((p,n)=>`<div class="reader-panel" id="reader-page-${n}" data-page="${n}" tabindex="0" role="button" aria-label="${lang==='en'?'Switch translation':'Орчуулгын хэл солих'}"><img src="${esc(p.url)}" alt="${t('chapter')} ${i+1}, ${lang==='en'?'page':'зураг'} ${n+1}" ${s.demo?'width="760" height="950"':''} ${n>0?'loading="lazy"':''}>${renderPageRegions(p,lang)}</div>`).join(''):`<div class="empty">Зураг оруулаагүй байна.</div>`}</article><div class="reader-dock"><span id="reader-position">1 / ${c.pages.length}</span><label class="page-jump">${lang==='en'?'Page':'Хуудас'}<select id="reader-page">${c.pages.map((p,n)=>`<option value="${n}">${n+1}</option>`).join('')}</select></label><div class="reading-progress"><span id="reading-progress-fill"></span></div><a href="#story/${id}" aria-label="${t('details')}">☷</a><button id="reader-top" aria-label="${lang==='en'?'Back to top':'Эхлэл рүү'}">↑</button></div><div class="reader-controls">${i>0?`<a class="btn secondary" href="#read/${id}/${s.chapters[i-1].id}">← Өмнөх</a>`:''}<a class="btn secondary" href="#story/${id}">${t('details')}</a>${i<s.chapters.length-1?`<a class="btn" href="#read/${id}/${s.chapters[i+1].id}">Дараах →</a>`:''}</div>`}
function admin(tab='library'){if(!canManage())return ownerOnlyPage();return `<div class="container"><div class="page-title"><div class="eyebrow">CREATOR WORKSPACE</div><h1>Удирдлагын хэсэг</h1><p>Бүтээл, бүлэг, зураг болон орчуулгаа нэг дороос.</p></div><div class="notice">Бүтээл, бүртгэл, VIP серверт; байршуулсан зураг хамгаалалттай хадгалалтад хадгалагдана. <button class="btn secondary" data-cloud-users>Хэрэглэгчид</button></div><div class="admin-tabs">${[['library','Бүтээлүүд'],['chapters','Бүлэг, зураг'],['videos','Видео'],['vip','VIP төлбөр'],['ads','Зар'],['translate','Орчуулга'],['pages','Зураг удирдах'],['status','Төслийн төлөв']].map(([id,name])=>`<a class="${tab===id?'active':''}" href="${id==='status'?'#status':'#admin/'+id}">${name}</a>`).join('')}</div>${restoreUndo?'<div class="undo-banner"><span>Нөөцөөс сэргээсэн өөрчлөлтүүд.</span><button class="btn secondary" id="undo-restoration">↶ Сэргээхийг буцаах</button></div>':''}${tab==='ads'?adsAdmin():tab==='vip'?vipAdmin():tab==='videos'?videoAdmin():tab==='chapters'?chapterAdmin():tab==='translate'?translationAdmin():tab==='pages'?pageAdmin():libraryAdmin()}</div>`}
function seriesOptions(){return state.series.map(s=>`<option value="${s.id}">${esc(s.mn)}</option>`).join('')}
function libraryAdmin(){return `<div class="metric-grid"><div class="metric"><small>Бүтээл</small><strong>${state.series.length}</strong></div><div class="metric"><small>Бүлэг</small><strong>${state.series.reduce((n,s)=>n+s.chapters.length,0)}</strong></div><div class="metric"><small>Зураг</small><strong>${state.series.reduce((n,s)=>n+s.chapters.reduce((m,c)=>m+c.pages.length,0),0)}</strong></div></div><div class="admin-layout"><section class="panel"><h2>Бүтээл нэмэх</h2><form id="add-series" class="form"><label>Монгол нэр<input name="mn" required maxlength="100"></label><label>Англи нэр<input name="en" maxlength="100"></label><label>Хавтасны URL<input name="cover" type="url" placeholder="https://…" required></label><label>Төрөл<select name="genre">${['fantasy','action','romance','adventure','scifi'].map(g=>`<option value="${g}">${MN[g]}</option>`).join('')}</select></label><label>Тайлбар<textarea name="description" required maxlength="3000"></textarea></label><label class="check"><input name="mature" type="checkbox"> Secret · VIP ангилалд оруулах (18+)</label><label class="check"><input name="rights" type="checkbox" required> Энэ бүтээлийг ашиглах эрхтэй.</label><button class="btn">Бүтээл нэмэх +</button></form></section><section class="panel"><h2>Бүтээлийн сан</h2>${state.series.map(s=>`<div class="manage-row"><img class="admin-cover" src="${esc(s.cover)}" alt=""><div class="title"><p>${esc(s.mn)}</p><span class="tiny">${s.chapters.length} бүлэг ${s.mature?'· Secret / VIP / 18+':s.demo?'· Жишээ':''}</span></div><button class="edit-button" data-edit-series="${s.id}">Засах</button><button class="danger" data-delete-series="${s.id}">Устгах</button></div>`).join('')}<p class="tiny">Устгах үед дахин баталгаажуулна.</p><div class="backup-box"><h3>Бүтээлүүдээ нөөцлөөрэй</h3><p>Браузерийн өгөгдөл цэвэрлэхээс өмнө зураг, орчуулгаа нэг JSON файлд татаж аваарай.</p><button id="export-library" class="btn secondary">↓ Нөөц файл татах</button><label class="restore-label">↑ Нөөцөөс сэргээх<input id="restore-backup" type="file" accept="application/json,.json"></label><p class="tiny">Сэргээхээс өмнө агуулгыг нь харуулж баталгаажуулна.</p></div></section></div>`}
function chapterAdmin(){return `<div class="admin-layout"><section class="panel"><h2>Бүлэг, олон зураг нэмэх</h2><form id="add-chapter" class="form"><label>Бүтээл<select name="series" required>${seriesOptions()}</select></label><label>Бүлгийн нэр<input name="name" required maxlength="100" placeholder="Бүлэг 1 — Эхлэл"></label><label>Англи нэр<input name="nameEn" maxlength="100"></label><label>Зураг оруулах · 19+ зураг дэмжинэ<input name="files" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label><div id="upload-summary" class="upload-summary" aria-live="polite">Зургаа нэг дор сонгох эсвэл доорх URL хэсгийг ашиглаарай.</div><label>Эсвэл зургийн URL · мөр бүрд нэг<textarea name="urls" placeholder="https://example.com/page-01.jpg&#10;https://example.com/page-02.jpg"></textarea></label><p class="tiny">Файлуудыг нэрээр эрэмбэлнэ. URL-үүд бичсэн дарааллаар нэмэгдэнэ. Нэг файл дээд тал нь 15 MB.</p><label class="check"><input name="rights" type="checkbox" required> Зургуудыг нийтлэх зөвшөөрөлтэй.</label><button class="btn">Бүлэг хадгалах +</button></form></section><section class="panel"><h2>Бүлгүүд</h2>${state.series.map(s=>`<h3 style="font-size:13px;margin-top:25px">${esc(s.mn)}</h3>${s.chapters.map((c,i)=>`<div class="manage-row"><div class="title"><p>${i+1}. ${esc(c.name)}</p><span class="tiny">${c.pages.length} зураг</span></div><button data-move="${s.id}/${c.id}/-1" aria-label="Дээш зөөх" ${i===0?'disabled':''}>↑</button><button data-move="${s.id}/${c.id}/1" aria-label="Доош зөөх" ${i===s.chapters.length-1?'disabled':''}>↓</button><button class="danger" data-delete-chapter="${s.id}/${c.id}">Устгах</button></div>`).join('')}`).join('')}</section></div>`}
function translationAdmin(){return `<div class="notice">Гараар орчуулах студи · AI сервер холбогдоогүй. Нэг зурагт олон ярианы хэсэг нэмээд, тус бүрийн байрлал болон текстийг хадгална.</div><div class="translation-studio"><section class="panel translation-sidebar"><div class="section-head"><h2>Орчуулгын студи</h2><span class="badge">MN / EN</span></div><form id="translate" class="form"><label>Бүтээл<select id="translation-series" name="series">${seriesOptions()}</select></label><div class="studio-select-row"><label>Бүлэг<select id="translation-chapter" name="chapter"></select></label><label>Хуудас<select id="translation-page" name="page"></select></label></div><div class="region-heading"><strong>Ярианы хэсгүүд</strong><button type="button" id="add-region">+ Хэсэг нэмэх</button></div><div id="region-list" class="region-list"></div><label>Монгол орчуулга<textarea name="mn" maxlength="10000" placeholder="Энэ хэсгийн Монгол орчуулга…"></textarea></label><label>Англи текст<textarea name="en" maxlength="10000" placeholder="Original English text…"></textarea></label><div class="geometry-grid"><label>X · зүүнээс %<input type="number" name="rx" min="0" max="99" step="any"></label><label>Y · дээрээс %<input type="number" name="ry" min="0" max="99" step="any"></label><label>Өргөн %<input type="number" name="rw" min="1" max="100" step="any"></label><label>Өндөр %<input type="number" name="rh" min="1" max="100" step="any"></label></div><div class="studio-select-row"><label>Үсгийн хэмжээ<input type="number" name="font" min="10" max="40" step="any"></label><label>Дэвсгэр<select name="bg"><option value="white">Цагаан</option><option value="cream">Цайвар шар</option><option value="dark">Бараан</option><option value="clear">Тунгалаг</option></select></label></div><div class="region-tools"><button type="button" id="remove-region" class="danger">Хэсэг хасах</button><button type="button" id="undo-region" class="text-link" disabled>↶ Буцаах</button></div><div id="translation-save-status" role="status" class="draft-status">Хадгалсан</div><button class="btn" type="submit">Орчуулга хадгалах</button></form></section><section class="studio-preview"><div class="preview-toolbar"><div><span class="eyebrow">LIVE PREVIEW</span><h3>Уншигч дээр харагдах байдал</h3></div><div class="preview-language"><button id="preview-mn" class="chip selected">MN</button><button id="preview-en" class="chip">EN</button></div></div><div id="translation-canvas" class="translation-canvas"><img id="translation-preview" alt="Сонгосон хуудас"><div id="preview-regions"></div></div><p class="tiny">Хэсгийг чирж зөөх эсвэл X / Y утгаар байрлуулна. Орчуулгын үсэг, дэвсгэр нь уншигч дээр мөн адил харагдана.</p><div id="studio-reader-link"></div></section></div>`}
function status(){if(window.MUR_CLOUDFLARE)return '<div class="container page-bottom"><h1>Sakitoru · Cloudflare</h1><p>Бүртгэл, админ, VIP хүсэлт болон гараар батлах серверийн хувилбар.</p><p>AI орчуулга, QPay холбогдоогүй. Банкны дансыг админ → VIP төлбөр хэсэгт тохируулна.</p><p>Хавчуурга, уншсан байрлал энэ браузерт хадгалагдана.</p></div>';if(window.MUR_STATIC)return '<div class="container page-bottom"><div class="page-title"><h1>Sakitoru · Уншигчийн хувилбар</h1></div><section class="panel"><p>✓ Каталог, хайлт, төрөл шүүлтүүр</p><p>✓ MN / EN уншигч, хадгалсан жагсаалт, уншсан хуудас</p><p>✓ Утасны неон дизайн, унших өргөн ба дэвсгэр</p><p>○ AI орчуулга — түр хойшлуулсан</p><p>○ Нэвтрэлт, админ, VIP — Cloudflare сервертэй холбогдоогүй</p><p>Хадгалсан жагсаалт, уншсан байрлал зөвхөн энэ браузерт хадгалагдана. Каталогт жишээ бүтээлүүд байна.</p></section></div>';return `<div class="container page-bottom"><div class="page-title"><div class="eyebrow">PROJECT STATUS · BETA</div><h1>Баталгаажуулалтын төлөв</h1><p>Холбогдоогүй үйлчилгээг бэлэн гэж тэмдэглэхгүй.</p></div><section class="panel">${[['Каталог, хайлт, төрлийн шүүлтүүр','Браузерийн хувилбар',true],['MN / EN уншигч, хадгалсан жагсаалт','Төхөөрөмжийн хадгалалт',true],['Бүлэг нэмэх, устгах, зөөх; 19+ зураг','Төхөөрөмжийн хадгалалт',true],['Орчуулга гараар засах, зураг дээр харуулах','Браузерийн хувилбар',true],['Өмнөх GitHub дахь 5 ажил','MVP код байна · бүрэн тест хийгдээгүй',false],['Бүртгэл · төрсөн огноо','Серверийн бүртгэл',true],['AI: Солонгос / Англи → Монгол','Сервер холбогдоогүй',false],['Secret · VIP','Үнэ, дансаа тохируулж, төлбөрийг гараар батална',true],['Зөвшөөрөлтэй контентоор Beta','Эх бүтээлийн жишээнүүдтэй',false]].map(([a,b,ok])=>`<div class="status-row ${ok?'ok':''}"><span>${a}</span><span>${ok?'◌ ':''}${b}</span></div>`).join('')}</section><div class="notice">Дараагийн алхам: 1. GitHub дахь манхвагийн MVP-г энэ хувилбартай нэгтгэж шалгах. 2. Бүтээл, зургийн серверийн хадгалалтыг холбох. 3. VIP үнэ, дансаа тохируулж, бодит төлбөрийн урсгалыг тестлэх.</div>${canManage()?'<a href="#admin" class="btn secondary">Удирдлага →</a>':''}</div>`}
function auth(mode){if(window.MUR_STATIC){modal('<h2>Нэвтрэлт хараахан холбогдоогүй</h2><p>Манхва унших, хадгалах, уншсан хэсгээс үргэлжлүүлэх боломжтой. Бүртгэл, админ, VIP серверийг дараагийн тохиргоогоор холбоно.</p>');return;}if(typeof mode==='string')authMode=mode;modal(accountPanel())}
function about(){return `<div class="container page-bottom"><div class="page-title"><div class="eyebrow">ABOUT SAKITORU</div><h1>Түүх бүр шинэ ертөнц.</h1><p>Sakitoru — Монгол, Англи хэлээр манхва унших, орчуулах платформын Beta хувилбар.</p></div><section class="panel"><h2>Унших эрх ба бүтээлүүд</h2><p style="line-height:2;color:#b5a3c6">Энэ хувилбарын зургаан бүтээл нь платформд зориулсан эх зураглал, жишээ өгүүлэмжтэй. Гуравдагч талын манхва оруулаагүй. Бодит контентыг зохиогч эсвэл эрх эзэмшигчийн зөвшөөрлөөр нэмнэ.</p><p class="tiny">VIP төлбөр болон AI орчуулга хараахан холбогдоогүй.</p><a href="#status" class="btn secondary">Төслийн төлөв →</a></section></div>`}
function translationSelect(changed='series'){const f=$('#translate');if(!f)return;let savedLocation=null;if(changed==='init'){try{savedLocation=JSON.parse(localStorage.getItem('mur-studio-location'))}catch{}if(savedLocation&&state.series.some(s=>s.id===savedLocation.series))f.series.value=savedLocation.series}const s=state.series.find(x=>x.id===f.series.value);if(changed==='series'||changed==='init')f.chapter.innerHTML=(s?.chapters||[]).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');if(savedLocation&&s?.chapters.some(c=>c.id===savedLocation.chapter))f.chapter.value=savedLocation.chapter;const c=s?.chapters.find(c=>c.id===f.chapter.value);if(changed!=='page')f.page.innerHTML=(c?.pages||[]).map((p,i)=>`<option value="${i}">Зураг ${i+1}</option>`).join('');if(savedLocation&&c?.pages[savedLocation.page])f.page.value=savedLocation.page;loadRegionPage()}
function route(){if(!initialized)return;window.MurAds?.beforeRoute();pageObserver?.disconnect();const parts=(location.hash.slice(1)||'home').split('/'),page=parts[0];syncAdminLinks();if(page==='admin'&&!canManage()){$('#app').innerHTML=ownerOnlyPage();document.body.classList.remove('is-reading','focus-reading');renderMobileNav('menu');return}if(page==='vip'){location.replace('#menu/vip');return}if(page==='saved'){location.replace('#menu/saved');return}if(['story','read'].includes(page)&&state.series.find(s=>s.id===parts[1])?.mature&&!ageConfirmed()){$('#app').innerHTML=ageGate();document.body.classList.remove('is-reading','focus-reading');renderMobileNav('secret');return}document.body.classList.toggle('is-reading',page==='read');document.body.classList.toggle('focus-reading',page==='read'&&readerPrefs.focus);document.body.classList.toggle('narrow-reading',readerPrefs.narrow);document.body.classList.toggle('hide-reader-text',readerPrefs.hideText);document.documentElement.lang=lang;$('#language').innerHTML=(lang==='mn'?'MN':'EN')+' <span>⌄</span>';$('#login').innerHTML=headerAccountLabel()+' <span>↗</span>';document.querySelectorAll('[data-nav]').forEach(a=>{const k=a.dataset.nav;a.childNodes[0].textContent=t(k)+(k==='updates'?' ':'');a.classList.toggle('active',page===k||(page==='story'&&k==='catalog'))});$('#app').innerHTML=page==='menu'?menuPage(parts[1]||'overview'):page==='secret'?(ageConfirmed()?catalog(false,true):ageGate()):page==='videos'?videosPage():page==='watch'?watchVideo(parts[1]):page==='home'?home():page==='catalog'?catalog():page==='story'?story(parts[1]):page==='read'?reader(parts[1],parts[2]):page==='updates'?`<div class="container page-bottom"><div class="page-title"><h1>${t('latest')}</h1><p>${t('latestsub')}</p></div><div class="update-list">${updates()}</div></div>`:page==='admin'?admin(parts[1]):page==='status'?status():page==='about'?about():missing();renderMobileNav(page);syncAdminLinks();if(page==='story')refreshStoryChapters();if(page==='admin'&&parts[1]==='translate')translationSelect('init');if(page==='admin'&&parts[1]==='pages')pageEditorLoad();if(page==='admin'&&parts[1]==='vip')loadVipAdmin();if(page==='admin'&&parts[1]==='ads')loadAdsAdmin();if(page==='read'){const s=state.series.find(s=>s.id===parts[1]);if(s?.chapters.some(c=>c.id===parts[2])){if(state.history?.series!==parts[1]||state.history?.chapter!==parts[2]){const next=clone();next.history={series:parts[1],chapter:parts[2]};persist(next).catch(()=>{})}setupReader(parts[1],parts[2])}}window.MurAds?.refresh()}
window.addEventListener('hashchange',()=>{undoSnapshot=null;if($('#modal').open)$('#modal').close();route();window.scrollTo({top:0,behavior:'instant'})});
$('#language').onclick=()=>{lang=lang==='mn'?'en':'mn';localStorage.setItem('mur-lang',lang);route()};$('#login').onclick=auth;$('#search-toggle').onclick=()=>{if(location.hash==='#catalog')$('#search')?.focus();else{location.hash='catalog';setTimeout(()=>$('#search')?.focus(),80)}};$('#modal .close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function confirmDelete(kind,id){modal(`<h2>${kind==='series'?'Бүтээл устгах уу?':'Бүлэг устгах уу?'}</h2><p>Холбогдох зураг, орчуулга энэ браузерийн сангаас устна. Энэ үйлдлийг буцаах боломжгүй.</p><button class="btn" data-confirm-delete="${kind}/${id}">Тийм, устгах</button> <button class="btn secondary" data-close>Болих</button>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(e.target.closest('[data-page]')){const p=e.target.closest('[data-page]'),parts=location.hash.split('/'),s=state.series.find(s=>s.id===parts[1]),c=s?.chapters.find(c=>c.id===parts[2]),item=c?.pages[Number(p.dataset.page)];if(item){const current=p.dataset.regionLang||lang,nextLang=current==='mn'?'en':'mn';p.dataset.regionLang=nextLang;p.querySelectorAll('.translation').forEach(box=>box.remove());p.insertAdjacentHTML('beforeend',renderPageRegions(item,nextLang))}}if(!b)return;try{if(b.hasAttribute('data-close'))$('#modal').close();if(b.dataset.filter){filter=b.dataset.filter;route()}if(b.dataset.save){const n=clone(),id=b.dataset.save;n.saved=n.saved.includes(id)?n.saved.filter(x=>x!==id):[...n.saved,id];await persist(n);route();toast(n.saved.includes(id)?(lang==='en'?'Added to your library':'Миний санд хадгаллаа'):(lang==='en'?'Removed from library':'Миний сангаас хаслаа'))}if(b.dataset.readlang){captureReaderPosition();lang=b.dataset.readlang;localStorage.setItem('mur-lang',lang);route()}if(b.dataset.deleteSeries)confirmDelete('series',b.dataset.deleteSeries);if(b.dataset.deleteChapter)confirmDelete('chapter',b.dataset.deleteChapter);if(b.dataset.confirmDelete){const [kind,id,cid]=b.dataset.confirmDelete.split('/'),n=clone();if(kind==='series'){n.series=n.series.filter(s=>s.id!==id);n.saved=n.saved.filter(x=>x!==id);if(n.history?.series===id)n.history=null}else{const s=n.series.find(s=>s.id===id);s.chapters=s.chapters.filter(c=>c.id!==cid);if(n.history?.chapter===cid)n.history=null}await persist(n);$('#modal').close();route();toast('Устгалаа')}if(b.dataset.move){const [sid,cid,dir]=b.dataset.move.split('/'),n=clone(),s=n.series.find(s=>s.id===sid),i=s.chapters.findIndex(c=>c.id===cid),j=i+Number(dir);if(j>=0&&j<s.chapters.length){[s.chapters[i],s.chapters[j]]=[s.chapters[j],s.chapters[i]];await persist(n);route()}}}catch(err){toast('Хадгалж чадсангүй. Төхөөрөмжийн сул зайг шалгана уу.')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-page]')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#cards').innerHTML=grid(filtered(catalogList(isSavedView(),location.hash==='#secret')));if($('#result-count'))$('#result-count').textContent=filtered(catalogList(isSavedView(),location.hash==='#secret')).length+' '+(lang==='en'?'stories':'бүтээл')}});
document.addEventListener('change',e=>{if(e.target.id==='translation-series')translationSelect();if(e.target.id==='translation-chapter')translationSelect('chapter');if(e.target.id==='translation-page')translationSelect('page')});
function safeURL(v){const u=new URL(v);if(!['https:','http:'].includes(u.protocol))throw Error('Зөвхөн https/http зургийн URL оруулна уу.');return u.href}
async function fileURL(file){if(file.size>15*1024*1024)throw Error(file.name+': 15 MB-аас их байна.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error(file.name+': PNG, JPEG, WEBP, GIF файл сонгоно уу.');return new Promise((res,rej)=>{const f=new FileReader();f.onload=()=>res(f.result);f.onerror=()=>rej(Error('Файл уншиж чадсангүй.'));f.readAsDataURL(file)})}
document.addEventListener('submit',async e=>{const f=e.target;if(!['add-series','add-chapter','translate'].includes(f.id))return;e.preventDefault();const btn=f.querySelector('button[type="submit"],button.btn');btn.disabled=true;try{const n=clone(),data=new FormData(f);if(f.id==='add-series'){const mn=data.get('mn').trim();if(!mn)throw Error('Бүтээлийн нэр оруулна уу.');n.series.push({id:uid(),mn,en:data.get('en').trim(),cover:safeURL(data.get('cover')),genres:[data.get('genre')],description:data.get('description').trim(),chapters:[],demo:false,mature:data.get('mature')==='on'})}else if(f.id==='add-chapter'){const s=n.series.find(x=>x.id===data.get('series'));if(!s)throw Error('Эхлээд бүтээл нэмнэ үү.');const name=data.get('name').trim();if(!name)throw Error('Бүлгийн нэр оруулна уу.');const files=Array.from(f.files.files).sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));const urls=data.get('urls').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(safeURL);if(!files.length&&!urls.length)throw Error('Хамгийн багадаа нэг зураг эсвэл URL оруулна уу.');const imported=[];for(const file of files)imported.push({url:await fileURL(file),mn:'',en:''});s.chapters.push({id:uid(),name,nameEn:data.get('nameEn').trim(),pages:[...imported,...urls.map(url=>({url,mn:'',en:''}))]})}else{const s=n.series.find(x=>x.id===data.get('series')),c=s?.chapters.find(c=>c.id===data.get('chapter')),p=c?.pages[Number(data.get('page'))];if(!p)throw Error('Хуудас сонгоно уу.');syncRegionFields();p.regions=studio.regions.map(normalizeRegion);p.mn=p.regions.map(r=>r.mn).filter(Boolean).join('\n');p.en=p.regions.map(r=>r.en).filter(Boolean).join('\n')}await persist(n);toast('Амжилттай хадгаллаа');if(f.id!=='translate')route();else{studio.dirty=false;localStorage.removeItem('mur-studio:'+studio.key);updateStudioStatus()}}catch(err){toast(err.name==='QuotaExceededError'?'Браузерийн хадгалах зай дүүрсэн.':(err.message||'Хадгалж чадсангүй.'))}finally{btn.disabled=false}});

let pageObserver=null, readerSession=0, readerRestoring=false;
if('scrollRestoration' in history)history.scrollRestoration='manual';
const readerPrefs=(()=>{try{return JSON.parse(localStorage.getItem('mur-reader-prefs'))||{focus:false,narrow:false,hideText:false}}catch{return {focus:false,narrow:false,hideText:false}}})();
function progressFor(sid,cid){try{return JSON.parse(localStorage.getItem('mur-progress:'+sid+':'+cid))||{page:0}}catch{return {page:0}}}
function continueBand(fallback){const h=state.history,s=h&&state.series.find(x=>x.id===h.series&&!x.mature),c=s?.chapters.find(x=>x.id===h.chapter),p=c?progressFor(s.id,c.id):null;return `<div class="reading-band upgraded"><img src="${esc(s?.cover||fallback.cover)}" alt=""><div class="continue-text"><span class="eyebrow">${lang==='en'?'PICK UP YOUR STORY':'ҮРГЭЛЖЛҮҮЛЭН УНШИХ'}</span><h3>${s?esc(title(s)):t('continue')}</h3><p>${c?`${t('chapter')} ${s.chapters.indexOf(c)+1} · ${lang==='en'?'Page':'Хуудас'} ${Math.min(p.page+1,c.pages.length)} / ${c.pages.length}`:t('contdesc')}</p>${c?`<div class="continue-progress"><span style="width:${c.pages.length?(p.page+1)/c.pages.length*100:0}%"></span></div>`:''}</div><a class="btn" href="${c?'#read/'+s.id+'/'+c.id:'#story/'+fallback.id}">${c?t('resume'):t('details')} →</a></div>`}
function renderMobileNav(page){$('#mobile-nav')?.remove();const el=document.createElement('nav');el.id='mobile-nav';el.setAttribute('aria-label',lang==='en'?'Mobile navigation':'Утасны цэс');el.innerHTML=[['home','⌂'],['catalog','▤'],['secret','◈'],['videos','▷'],['menu','☰']].map(([key,icon])=>`<a href="#${key}" class="${page===key?'active':''}"><span>${icon}</span>${key==='admin'?(lang==='en'?'Studio':'Удирдлага'):t(key)}</a>`).join('');document.body.append(el)}
function setReaderPosition(index,save=true){const count=document.querySelectorAll('.reader-panel').length;if(!count)return;const n=Math.max(0,Math.min(Number(index)||0,count-1));$('#reader-position').textContent=`${n+1} / ${count}`;$('#reader-page').value=String(n);$('#reading-progress-fill').style.width=((n+1)/count*100)+'%';if(save){const [,sid,cid]=location.hash.split('/');if(n===count-1)window.MurAds?.chapterCompleted(sid,cid);try{localStorage.setItem('mur-progress:'+sid+':'+cid,JSON.stringify({page:n,completed:progressFor(sid,cid).completed||n===count-1}))}catch{}}}
function captureReaderPosition(){if(!document.body.classList.contains('is-reading'))return;const panels=[...document.querySelectorAll('.reader-panel')];const match=panels.findIndex(p=>p.getBoundingClientRect().bottom>180);if(match>=0)setReaderPosition(match)}
function setupReader(sid,cid){const session=++readerSession;const n=Math.min(progressFor(sid,cid).page||0,document.querySelectorAll('.reader-panel').length-1);setReaderPosition(n,false);readerRestoring=true;$('.reader').dataset.ready='false';requestAnimationFrame(()=>{if(session!==readerSession||!document.body.classList.contains('is-reading'))return;if(n>0)$('#reader-page-'+n)?.scrollIntoView({block:'start',behavior:'instant'});readerRestoring=false;$('.reader').dataset.ready='true';pageObserver=new IntersectionObserver(entries=>{if(readerRestoring)return;for(const e of entries)if(e.isIntersecting)setReaderPosition(Number(e.target.dataset.page))},{rootMargin:'-20% 0px -55% 0px',threshold:0});document.querySelectorAll('.reader-panel').forEach(el=>pageObserver.observe(el))})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(['focus-mode','reader-width','reader-text'].includes(b.id)){const currentPage=Number($('#reader-page')?.value||0);readerRestoring=true;const key=b.id==='focus-mode'?'focus':b.id==='reader-width'?'narrow':'hideText';readerPrefs[key]=!readerPrefs[key];try{localStorage.setItem('mur-reader-prefs',JSON.stringify(readerPrefs))}catch{}document.body.classList.toggle('focus-reading',readerPrefs.focus);document.body.classList.toggle('narrow-reading',readerPrefs.narrow);document.body.classList.toggle('hide-reader-text',readerPrefs.hideText);b.setAttribute('aria-pressed',String(key==='hideText'?!readerPrefs[key]:readerPrefs[key]));requestAnimationFrame(()=>{$('#reader-page-'+currentPage)?.scrollIntoView({block:'start',behavior:'instant'});setReaderPosition(currentPage);requestAnimationFrame(()=>{readerRestoring=false})});}if(b.id==='reader-top'){$('#reader-page-0')?.scrollIntoView({block:'start',behavior:'smooth'});setReaderPosition(0)}if(b.id==='export-library'){const blob=new Blob([JSON.stringify({format:'mur-backup-v1',created:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mur-library-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Нөөц файлыг татаж байна.')}});
document.addEventListener('change',e=>{if(e.target.id==='reader-page'){const n=Number(e.target.value);$('#reader-page-'+n)?.scrollIntoView({block:'start',behavior:'instant'});setReaderPosition(n)}if(e.target.id==='reader-chapter'){const [,sid]=location.hash.split('/');location.hash='read/'+sid+'/'+e.target.value}if(e.target.id==='catalog-sort'){sort=e.target.value;route()}if(e.target.matches('#add-chapter input[type=file]')){const files=Array.from(e.target.files).sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));$('#upload-summary').textContent=files.length?`${files.length} зураг · ${(files.reduce((n,f)=>n+f.size,0)/1024/1024).toFixed(1)} MB · ${files.slice(0,3).map(f=>f.name).join(', ')}${files.length>3?' …':''}`:'Зураг сонгоогүй байна.'}});



let editorSeries='',editorChapter='',undoSnapshot=null,pendingRestore=null,restoreUndo=null;
function pageAdmin(){return `<section class="panel page-bottom"><div class="section-head"><div><h2>Зураг удирдах</h2><p>Хуудас бүрээ шалгаж, эрэмбэлж, нэмэлт зураг оруулаарай.</p></div><span class="badge">PAGE STUDIO</span></div><div class="page-editor-select"><label>Бүтээл<select id="page-editor-series">${seriesOptions()}</select></label><label>Бүлэг<select id="page-editor-chapter"></select></label></div><div id="undo-panel"></div><div id="page-editor-content"></div></section>`}
function pageEditorLoad(chapterOnly=false){const ss=$('#page-editor-series'),cs=$('#page-editor-chapter');if(!ss)return;if(!chapterOnly&&state.series.some(s=>s.id===editorSeries))ss.value=editorSeries;editorSeries=ss.value;const s=state.series.find(s=>s.id===editorSeries);cs.innerHTML=(s?.chapters||[]).map((c,i)=>`<option value="${c.id}">${i+1}. ${esc(c.name)}</option>`).join('');if(s?.chapters.some(c=>c.id===editorChapter))cs.value=editorChapter;editorChapter=cs.value;renderPages()}
function renderUndo(){const el=$('#undo-panel');if(el)el.innerHTML=undoSnapshot?'<div class="undo-banner"><span>Сүүлийн өөрчлөлтийг буцаах боломжтой.</span><button class="btn secondary" id="undo-edit">↶ Буцаах</button></div>':''}
function renderPages(){const s=state.series.find(s=>s.id===editorSeries),c=s?.chapters.find(c=>c.id===editorChapter);renderUndo();$('#page-editor-content').innerHTML=!c?'<div class="empty">Эхлээд бүтээл, бүлэг нэмнэ үү.</div>':`<div class="page-editor-heading"><span>${c.pages.length} хуудас</span><a class="text-link" href="#read/${s.id}/${c.id}">Уншигчаар харах ↗</a></div><div class="page-thumbnails">${c.pages.map((p,i)=>`<article class="page-thumbnail"><div class="page-thumb"><img src="${esc(p.url)}" alt="Хуудас ${i+1}" loading="lazy"><span>${String(i+1).padStart(2,'0')}</span></div><div class="page-thumb-meta"><span class="${pageRegions(p).some(r=>r.mn)?'translated':'untranslated'}">${pageRegions(p).some(r=>r.mn)?'● Монгол орчуулгатай':'○ Орчуулгагүй'}</span><div><button data-page-move="${i}/-1" ${i===0?'disabled':''} aria-label="Хуудас ${i+1} дээш">↑</button><button data-page-move="${i}/1" ${i===c.pages.length-1?'disabled':''} aria-label="Хуудас ${i+1} доош">↓</button><button data-page-remove="${i}" class="danger" aria-label="Хуудас ${i+1} хасах">×</button></div></div></article>`).join('')}</div><form class="form append-pages" id="append-pages"><h3>Энэ бүлэгт зураг нэмэх</h3><label>Зураг сонгох<input name="images" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label><label>Зургийн URL · мөр бүрд нэг<textarea name="urls" placeholder="https://…"></textarea></label><p class="tiny">Сонгосон файлууд нэрийн дарааллаар, дараа нь URL-үүд бүлгийн төгсгөлд нэмэгдэнэ.</p><label class="check"><input type="checkbox" required> Эдгээр зургийг ашиглах эрхтэй.</label><button class="btn">Зураг нэмэх +</button></form>`}
function editSeries(id){const s=state.series.find(s=>s.id===id);if(!s)return;modal(`<div class="eyebrow">STORY EDITOR</div><h2>Бүтээл засах</h2><form id="edit-series" data-id="${s.id}" class="form"><label>Монгол нэр<input name="mn" required maxlength="100" value="${esc(s.mn)}"></label><label>Англи нэр<input name="en" maxlength="100" value="${esc(s.en)}"></label><label>Хавтасны URL<input name="cover" value="${esc(s.cover)}" required></label><label>Төрөл<select name="genre">${['fantasy','action','romance','adventure','scifi'].map(g=>`<option value="${g}" ${s.genres[0]===g?'selected':''}>${MN[g]}</option>`).join('')}</select></label><label>Монгол тайлбар<textarea name="description" required maxlength="3000">${esc(s.description)}</textarea></label><label class="check"><input name="mature" type="checkbox" ${s.mature?'checked':''}> Secret · VIP ангилал (18+)</label><label>Англи тайлбар<textarea name="descriptionEn" maxlength="3000">${esc(s.descriptionEn||'')}</textarea></label><button class="btn">Өөрчлөлт хадгалах</button></form>`)}
function assetURL(value){const v=String(value||'');if(/^art\/(?:cover-[0-5]\.svg|page-[0-2]\.(?:png|svg))$/.test(v))return v;if(/^data:image\/(?:png|jpeg|webp|gif);base64,[A-Za-z0-9+/=\r\n]+$/.test(v))return v;return safeURL(v)}
function validateBackup(raw){if(raw?.format!=='mur-backup-v1'||!Array.isArray(raw.data?.series))throw Error('Sakitoru-ийн зөв нөөц файл сонгоно уу.');const ids=new Set();let pageCount=0;const series=raw.data.series.map(s=>{if(!/^[a-zA-Z0-9_-]{1,100}$/.test(s.id)||ids.has(s.id)||!Array.isArray(s.chapters))throw Error('Бүтээлийн бүтэц эсвэл дугаар буруу байна.');ids.add(s.id);const cids=new Set();const chapters=s.chapters.map(c=>{if(!/^[a-zA-Z0-9_-]{1,100}$/.test(c.id)||cids.has(c.id)||!Array.isArray(c.pages))throw Error('Бүлгийн өгөгдөл буруу байна.');cids.add(c.id);pageCount+=c.pages.length;return {id:c.id,name:String(c.name||'Бүлэг').slice(0,100),nameEn:String(c.nameEn||'').slice(0,100),pages:c.pages.map(p=>({url:assetURL(p.url),mn:String(p.mn||'').slice(0,10000),en:String(p.en||'').slice(0,10000),...(Array.isArray(p.regions)?{regions:p.regions.slice(0,100).map(normalizeRegion)}:{})}))}});return {id:s.id,mn:String(s.mn||'Нэргүй бүтээл').slice(0,100),en:String(s.en||'').slice(0,100),cover:assetURL(s.cover),genres:(Array.isArray(s.genres)?s.genres:[]).filter(g=>['fantasy','action','romance','adventure','scifi'].includes(g)).slice(0,2),description:String(s.description||'').slice(0,3000),descriptionEn:String(s.descriptionEn||'').slice(0,3000),demo:s.demo===true,mature:s.mature===true,title:String(s.title||'').slice(0,80),chapters}});return {series,pageCount,videos:validateVideos(raw.data.videos||[]),saved:Array.isArray(raw.data.saved)?raw.data.saved.filter(id=>ids.has(id)):[]}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.id==='undo-restoration'&&restoreUndo){await persist(restoreUndo);restoreUndo=null;route();toast('Сэргээхийн өмнөх хувилбарт буцаалаа.')}if(b.dataset.editSeries)editSeries(b.dataset.editSeries);if(b.hasAttribute('data-page-move')||b.hasAttribute('data-page-remove')){const n=clone(),c=n.series.find(s=>s.id===editorSeries)?.chapters.find(c=>c.id===editorChapter);if(!c)return;const previous=clone();if(b.hasAttribute('data-page-remove'))c.pages.splice(Number(b.dataset.pageRemove),1);else{const [i,dir]=b.dataset.pageMove.split('/').map(Number),j=i+dir;if(j<0||j>=c.pages.length)return;[c.pages[i],c.pages[j]]=[c.pages[j],c.pages[i]]}await persist(n);undoSnapshot=previous;renderPages()}if(b.id==='undo-edit'&&undoSnapshot){const prev=undoSnapshot;await persist(prev);undoSnapshot=null;renderPages();toast('Сүүлийн өөрчлөлтийг буцаалаа.')}if(b.id==='confirm-restore'&&pendingRestore){const old=clone(),n=clone();for(const s of pendingRestore.series){const i=n.series.findIndex(x=>x.id===s.id);if(i<0)n.series.push(s);else n.series[i]=s}n.saved=[...new Set([...n.saved,...pendingRestore.saved])];n.videos=[...(n.videos||[]).filter(v=>!pendingRestore.videos.some(x=>x.id===v.id)),...pendingRestore.videos];await persist(n);restoreUndo=old;undoSnapshot=null;pendingRestore=null;$('#modal').close();route();toast('Нөөцөөс сэргээж хадгаллаа.')}}catch(err){toast(err.message||'Хадгалж чадсангүй.')}});
document.addEventListener('change',async e=>{if(e.target.id==='page-editor-series'){editorSeries=e.target.value;editorChapter='';pageEditorLoad(true)}if(e.target.id==='page-editor-chapter'){editorChapter=e.target.value;renderPages()}if(e.target.id==='restore-backup'){const file=e.target.files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('Нөөц файл 100 MB-аас их байна.');pendingRestore=validateBackup(JSON.parse(await file.text()));const overlap=pendingRestore.series.filter(s=>state.series.some(x=>x.id===s.id)).length;modal(`<div class="eyebrow">BACKUP PREVIEW</div><h2>Нөөцөөс сэргээх</h2><div class="restore-stats"><strong>${pendingRestore.series.length}<small>бүтээл</small></strong><strong>${pendingRestore.series.reduce((n,s)=>n+s.chapters.length,0)}<small>бүлэг</small></strong><strong>${pendingRestore.pageCount}<small>зураг</small></strong></div><p>Ижил дугаартай ${overlap} бүтээлийн зураг, орчуулгыг нөөц дэх хувилбараар солино. Бусад одоогийн бүтээл хадгалагдана.</p><button id="confirm-restore" class="btn">Сэргээж хадгалах</button> <button class="btn secondary" data-close>Болих</button>`)}catch(err){pendingRestore=null;toast(err instanceof SyntaxError?'JSON файлыг уншиж чадсангүй.':err.message)}e.target.value=''}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['edit-series','append-pages'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button.btn');b.disabled=true;try{const n=clone(),d=new FormData(f);if(f.id==='edit-series'){const s=n.series.find(s=>s.id===f.dataset.id);if(!s)throw Error('Бүтээл олдсонгүй.');const mn=d.get('mn').trim();if(!mn)throw Error('Монгол нэр оруулна уу.');const cover=assetURL(d.get('cover'));Object.assign(s,{mn,mature:d.get('mature')==='on',en:d.get('en').trim(),cover,genres:[d.get('genre'),...s.genres.filter(g=>g!==s.genres[0]&&g!==d.get('genre'))].slice(0,2),description:d.get('description').trim(),descriptionEn:d.get('descriptionEn').trim()});await persist(n);undoSnapshot=null;$('#modal').close();route()}else{const c=n.series.find(s=>s.id===editorSeries)?.chapters.find(c=>c.id===editorChapter);if(!c)throw Error('Бүлэг олдсонгүй.');const files=[...f.images.files].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true})),urls=d.get('urls').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).map(safeURL);if(!files.length&&!urls.length)throw Error('Зураг эсвэл URL оруулна уу.');const previous=clone();for(const file of files)c.pages.push({url:await fileURL(file),mn:'',en:''});c.pages.push(...urls.map(url=>({url,mn:'',en:''})));await persist(n);undoSnapshot=previous;renderPages()}toast('Амжилттай хадгаллаа.')}catch(err){toast(err.message||'Хадгалж чадсангүй.')}finally{b.disabled=false}});


let studio={key:'',regions:[],selected:0,dirty:false,preview:'mn',undo:null};
const regionBackgrounds={white:['#f7f4ff','#201d2c'],cream:['#fff4dc','#382b19'],dark:['#221b30','#f5eaff'],clear:['transparent','#f5eaff']};
function bounded(value,min,max,fallback){const n=Number(value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback}
function normalizeRegion(raw={}){const x=bounded(raw.x,0,99,9),y=bounded(raw.y,0,99,11);return {mn:String(raw.mn||'').slice(0,10000),en:String(raw.en||'').slice(0,10000),x,y,w:bounded(raw.w,1,100-x,Math.min(82,100-x)),h:bounded(raw.h,1,100-y,Math.min(10,100-y)),font:bounded(raw.font,10,40,18),bg:Object.hasOwn(regionBackgrounds,raw.bg)?raw.bg:'white'}}
function pageRegions(p){return Array.isArray(p.regions)?p.regions.map(normalizeRegion):(p.mn||p.en)?[normalizeRegion({mn:p.mn,en:p.en,...(/^art\/page-[0-2]\.png$/.test(p.url)?{x:6.6,y:5.3,w:86.8,h:11.6}:{})})]:[]}
function regionStyle(r){const [bg,ink]=regionBackgrounds[r.bg];return `left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%;font-size:clamp(9px,${r.font/7.6}cqw,40px);background:${bg};color:${ink}`}
function renderPageRegions(p,language){return pageRegions(p).map(r=>`<div class="translation region-overlay" style="${regionStyle(r)}">${esc(r[language]||(language==='mn'?'Монгол орчуулга оруулаагүй.':'English translation not added.'))}</div>`).join('')}
function currentStudioPage(){const f=$('#translate');return f&&state.series.find(s=>s.id===f.series.value)?.chapters.find(c=>c.id===f.chapter.value)?.pages[Number(f.page.value)]}
function loadRegionPage(){const f=$('#translate'),p=currentStudioPage();studio.key=p?`${f.series.value}:${f.chapter.value}:${f.page.value}`:'';try{localStorage.setItem('mur-studio-location',JSON.stringify({series:f.series.value,chapter:f.chapter.value,page:f.page.value}))}catch{}studio.regions=p?pageRegions(p):[];studio.selected=0;studio.dirty=false;studio.undo=null;try{const draft=JSON.parse(localStorage.getItem('mur-studio:'+studio.key));if(p&&draft&&Array.isArray(draft.regions)){studio.regions=draft.regions.slice(0,100).map(normalizeRegion);studio.dirty=true}}catch{}$('#translation-preview').src=p?.url||'art/cover-0.svg';$('#studio-reader-link').innerHTML=p?`<a class="btn secondary" href="#read/${f.series.value}/${f.chapter.value}">Уншигчаар нээх ↗</a>`:'';renderRegionList();loadRegionFields();renderStudioPreview()}
function updateStudioStatus(){const el=$('#translation-save-status');if(!el)return;el.classList.toggle('dirty',studio.dirty);el.textContent=studio.dirty?'● Ноорог · уншигчид харагдуулахын тулд хадгална уу.':'✓ Хадгалсан';$('#undo-region').disabled=!studio.undo}
function cacheStudioDraft(){studio.dirty=true;try{localStorage.setItem('mur-studio:'+studio.key,JSON.stringify({regions:studio.regions}))}catch{}updateStudioStatus()}
function syncRegionFields(){const f=$('#translate'),r=studio.regions[studio.selected];if(!f||!r)return;studio.regions[studio.selected]=normalizeRegion({mn:f.mn.value,en:f.en.value,x:f.rx.value,y:f.ry.value,w:f.rw.value,h:f.rh.value,font:f.font.value,bg:f.bg.value})}
function loadRegionFields(){const f=$('#translate'),r=studio.regions[studio.selected];if(!f)return;for(const name of ['mn','en','rx','ry','rw','rh','font','bg'])f.elements.namedItem(name).disabled=!r;f.mn.value=r?.mn||'';f.en.value=r?.en||'';f.rx.value=Number((r?.x??9).toFixed(1));f.ry.value=Number((r?.y??11).toFixed(1));f.rw.value=Number((r?.w??82).toFixed(1));f.rh.value=Number((r?.h??10).toFixed(1));f.font.value=r?.font??18;f.bg.value=r?.bg||'white';f.querySelector('[type=submit]').disabled=!currentStudioPage();$('#add-region').disabled=!currentStudioPage()||studio.regions.length>=100;$('#remove-region').disabled=!r;updateStudioStatus()}
function renderRegionList(){const el=$('#region-list');if(!el)return;el.innerHTML=studio.regions.length?studio.regions.map((r,i)=>`<button type="button" data-select-region="${i}" class="region-pill ${studio.selected===i?'active':''}">${String(i+1).padStart(2,'0')}<span>${r.mn?'●':'○'}</span></button>`).join(''):'<span class="tiny">Ярианы хэсэг нэмээд эхлээрэй.</span>'}
function renderStudioPreview(){const el=$('#preview-regions');if(!el)return;el.innerHTML=studio.regions.map((r,i)=>`<div role="button" tabindex="0" aria-label="Ярианы хэсэг ${i+1}" class="translation region-overlay studio-region ${studio.selected===i?'active':''}" data-studio-region="${i}" style="${regionStyle(r)}">${esc(r[studio.preview]||'Текстээ бичээрэй…')}<span class="region-handle">${i+1}</span></div>`).join('');$('#preview-mn').classList.toggle('selected',studio.preview==='mn');$('#preview-en').classList.toggle('selected',studio.preview==='en')}
function selectStudioRegion(i){syncRegionFields();studio.selected=i;renderRegionList();loadRegionFields();renderStudioPreview()}
document.addEventListener('input',e=>{if(e.target.closest('#translate')&&['mn','en','rx','ry','rw','rh','font','bg'].includes(e.target.name)){syncRegionFields();cacheStudioDraft();renderStudioPreview();renderRegionList()}});
document.addEventListener('change',e=>{if(e.target.closest('#translate')&&e.target.name==='bg'){syncRegionFields();cacheStudioDraft();renderStudioPreview()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-select-region'))selectStudioRegion(Number(b.dataset.selectRegion));if(b?.id==='add-region'){syncRegionFields();studio.undo=structuredClone(studio.regions);studio.regions.push(normalizeRegion({x:20,y:Math.min(75,20+studio.regions.length*12),w:60,h:10}));studio.selected=studio.regions.length-1;cacheStudioDraft();renderRegionList();loadRegionFields();renderStudioPreview()}if(b?.id==='remove-region'){studio.undo=structuredClone(studio.regions);studio.regions.splice(studio.selected,1);studio.selected=Math.max(0,studio.selected-1);cacheStudioDraft();renderRegionList();loadRegionFields();renderStudioPreview()}if(b?.id==='undo-region'&&studio.undo){studio.regions=studio.undo;studio.undo=null;studio.selected=0;cacheStudioDraft();renderRegionList();loadRegionFields();renderStudioPreview()}if(['preview-mn','preview-en'].includes(b?.id)){syncRegionFields();studio.preview=b.id==='preview-mn'?'mn':'en';renderStudioPreview()}const region=e.target.closest('[data-studio-region]');if(region&&Number(region.dataset.studioRegion)!==studio.selected)selectStudioRegion(Number(region.dataset.studioRegion))});
let regionDrag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-studio-region]');if(!el||e.button!==0)return;const i=Number(el.dataset.studioRegion);if(i!==studio.selected)selectStudioRegion(i);const r=studio.regions[i],rect=$('#translation-canvas').getBoundingClientRect();regionDrag={id:e.pointerId,i,x:e.clientX,y:e.clientY,startX:r.x,startY:r.y,width:rect.width,height:rect.height};$('#translation-canvas').setPointerCapture(e.pointerId);e.preventDefault()});
document.addEventListener('pointermove',e=>{if(!regionDrag||regionDrag.id!==e.pointerId)return;const d=regionDrag,r=studio.regions[d.i];r.x=bounded(d.startX+(e.clientX-d.x)/d.width*100,0,100-r.w,r.x);r.y=bounded(d.startY+(e.clientY-d.y)/d.height*100,0,100-r.h,r.y);const f=$('#translate');f.rx.value=r.x.toFixed(1);f.ry.value=r.y.toFixed(1);renderStudioPreview()});
function finishRegionDrag(){if(!regionDrag)return;regionDrag=null;cacheStudioDraft()}
document.addEventListener('pointerup',finishRegionDrag);document.addEventListener('pointercancel',finishRegionDrag);


let videoQuery='',videoCategory='all';
const videoTypes={all:['Бүгд','All'],animation:['Анимэйшн','Animation'],trailer:['Трейлер','Trailer'],short:['Богино видео','Short'],other:['Бусад','Other']};
const videoLabel=k=>videoTypes[k]?.[lang==='en'?1:0]||k;
function videoSource(value){const u=new URL(String(value).trim());if(u.protocol!=='https:')throw Error('HTTPS видео холбоос оруулна уу.');let id;if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname))id=u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|embed)\/([\w-]+)\/?$/)?.[1];else if(u.hostname==='youtu.be')id=u.pathname.slice(1);if(id&&/^[\w-]{11}$/.test(id))return {kind:'embed',url:'https://www.youtube-nocookie.com/embed/'+id};if(['vimeo.com','www.vimeo.com'].includes(u.hostname)&&/^\/\d+\/?$/.test(u.pathname))return {kind:'embed',url:'https://player.vimeo.com/video/'+u.pathname.split('/')[1]};if(/\.(mp4|webm)$/i.test(u.pathname))return {kind:'file',url:u.href};throw Error('YouTube, Vimeo эсвэл шууд .mp4 / .webm холбоос ашиглана уу.')}
function validateVideos(items){if(!Array.isArray(items)||items.length>1000)throw Error('Видеоны өгөгдөл буруу.');const ids=new Set();return items.map(v=>{if(!/^[\w-]{1,100}$/.test(v.id)||ids.has(v.id))throw Error('Видеоны дугаар буруу.');ids.add(v.id);videoSource(v.url);return {id:v.id,name:String(v.name||'Видео').slice(0,100),url:String(v.url),cover:v.cover?safeURL(v.cover):'',category:Object.hasOwn(videoTypes,v.category)&&v.category!=='all'?v.category:'other',description:String(v.description||'').slice(0,3000)}})}
function videoCard(v){return `<article class="video-card"><a href="#watch/${v.id}" class="video-thumb"><img src="${esc(v.cover||'art/scene-0.svg')}" alt="${esc(v.name)}" loading="lazy"><span class="video-play" aria-hidden="true">▷</span><span class="video-category">${videoLabel(v.category)}</span></a><h3><a href="#watch/${v.id}">${esc(v.name)}</a></h3><p>${esc(v.description||videoLabel(v.category))}</p></article>`}
function videoResults(){const list=(state.videos||[]).filter(v=>(videoCategory==='all'||v.category===videoCategory)&&(!videoQuery||`${v.name} ${v.description}`.toLocaleLowerCase().includes(videoQuery.toLocaleLowerCase())));return list.length?list.map(videoCard).join(''):`<div class="video-empty"><span>▷</span><h2>${lang==='en'?'No videos yet':'Одоогоор видео алга'}</h2><p>${videoQuery||videoCategory!=='all'?(lang==='en'?'Try another search or category.':'Хайлт эсвэл төрлөө өөрчлөөд үзээрэй.'):(lang==='en'?'Add your first video in the studio.':'Эхний видеоныхоо холбоосыг удирдлагын хэсгээс нэмээрэй.')}</p>${!videoQuery&&videoCategory==='all'?`<a class="btn secondary" href="#admin/videos">${lang==='en'?'Add video':'Видео нэмэх'} +</a>`:''}</div>`}
function videosPage(){return `<div class="container page-bottom"><section class="video-hero"><div><div class="eyebrow">Sakitoru / VIDEO COLLECTION</div><h1>${lang==='en'?'Stories in motion.':'Түүхүүд амилна.'}</h1><p>${lang==='en'?'Animation, trailers and short stories. Find your next watch.':'Анимэйшн, трейлер, богино түүхүүд. Дараагийн үзэх ертөнцөө нээгээрэй.'}</p><a href="#admin/videos" class="btn secondary">${lang==='en'?'Add video':'Видео нэмэх'} +</a></div><span class="video-hero-play" aria-hidden="true">▷</span></section><div class="section-head"><h2>${t('videos')} <small class="tiny">${(state.videos||[]).length}</small></h2><span class="badge">${lang==='en'?'FREE TO WATCH':'ҮНЭГҮЙ ҮЗЭХ'}</span></div><label class="searchbox"><span aria-hidden="true">⌕</span><input id="video-search" type="search" value="${esc(videoQuery)}" placeholder="${lang==='en'?'Search videos…':'Видео хайх…'}" aria-label="${lang==='en'?'Search videos':'Видео хайх'}"></label><div class="filters">${Object.keys(videoTypes).map(k=>`<button class="chip ${videoCategory===k?'selected':''}" data-video-filter="${k}" aria-pressed="${videoCategory===k}">${videoLabel(k)}</button>`).join('')}</div><div class="video-grid" id="video-results" aria-live="polite">${videoResults()}</div></div>`}
function watchVideo(id){const v=(state.videos||[]).find(v=>v.id===id);if(!v)return missing();const src=videoSource(v.url);return `<div class="container page-bottom"><a class="story-breadcrumb" href="#videos">← ${t('videos')}</a><div class="video-player">${src.kind==='file'?`<video controls playsinline preload="metadata" ${v.cover?`poster="${esc(v.cover)}"`:''} src="${esc(src.url)}"></video>`:`<iframe src="${esc(src.url)}" title="${esc(v.name)}" allow="fullscreen; picture-in-picture; encrypted-media" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`}</div><div class="video-description"><span class="tag">${videoLabel(v.category)}</span><h1>${esc(v.name)}</h1><p>${esc(v.description)}</p><p class="tiny">${lang==='en'?'If playback is unavailable, open the source:':'Тоглуулах боломжгүй бол эх холбоосоор нээгээрэй:'} <a class="text-link" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${lang==='en'?'Open video':'Видео нээх'} ↗</a></p></div>${sectionHead(lang==='en'?'More to watch':'Бусад видео','', '#videos')}<div class="video-grid">${(state.videos||[]).filter(x=>x.id!==id).slice(0,3).map(videoCard).join('')}</div></div>`}
function videoAdmin(){return `<div class="admin-layout page-bottom"><section class="panel"><h2>Видео нэмэх</h2><form id="add-video" class="form"><label>Видеоны нэр<input name="name" required maxlength="100"></label><label>Видеоны холбоос<input name="url" type="url" required placeholder="https://www.youtube.com/watch?v=…"></label><p class="tiny">YouTube, Vimeo эсвэл шууд MP4 / WebM холбоос. Гаднын үйлчилгээ embed тоглуулахыг зөвшөөрсөн байх шаардлагатай.</p><label>Нүүр зургийн URL · заавал биш<input name="cover" type="url" placeholder="https://…"></label><label>Төрөл<select name="category">${Object.keys(videoTypes).filter(k=>k!=='all').map(k=>`<option value="${k}">${videoTypes[k][0]}</option>`).join('')}</select></label><label>Тайлбар<textarea name="description" maxlength="3000"></textarea></label><label class="check"><input type="checkbox" required> Энэ видеог түгээх эрхтэй.</label><button class="btn">Видео хадгалах +</button></form></section><section class="panel"><h2>Видеоны сан · ${(state.videos||[]).length}</h2><p class="tiny">Энэ браузерт хадгална. Бүтээлүүд → Нөөц файл татах үйлдэл видеонуудыг мөн нөөцөлнө.</p>${(state.videos||[]).map(v=>`<div class="manage-row"><div class="title"><a href="#watch/${v.id}">${esc(v.name)} ↗</a><p class="tiny">${videoLabel(v.category)}</p></div><button class="danger" data-delete-video="${v.id}">Устгах</button></div>`).join('')||'<div class="empty">Видео оруулаагүй байна.</div>'}</section></div>`}
document.addEventListener('input',e=>{if(e.target.id==='video-search'){videoQuery=e.target.value;$('#video-results').innerHTML=videoResults()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.videoFilter){videoCategory=b.dataset.videoFilter;route()}if(b.dataset.deleteVideo)modal(`<h2>Видео устгах уу?</h2><p>Энэ браузерийн жагсаалтаас хасна.</p><button class="btn" data-confirm-video-delete="${esc(b.dataset.deleteVideo)}">Устгах</button> <button class="btn secondary" data-close>Болих</button>`);if(b.dataset.confirmVideoDelete)try{const n=clone();n.videos=(n.videos||[]).filter(v=>v.id!==b.dataset.confirmVideoDelete);await persist(n);$('#modal').close();route();toast('Видео устгалаа.')}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='add-video')return;e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const d=new FormData(f),name=d.get('name').trim();if(!name)throw Error('Видеоны нэр оруулна уу.');const url=d.get('url').trim();videoSource(url);const n=clone();n.videos=n.videos||[];n.videos.unshift({id:uid(),name,url,cover:d.get('cover').trim()?safeURL(d.get('cover').trim()):'',category:d.get('category'),description:d.get('description').trim()});await persist(n);route();toast('Видео хадгаллаа.')}catch(err){toast(err.message||'Хадгалж чадсангүй.')}finally{b.disabled=false}});

(async()=>{try{db=await openDB();const saved=await new Promise((res,rej)=>{const q=db.transaction('app').objectStore('app').get('state');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});if(saved?.series)state=saved;for(const series of state.series)for(const chapter of series.chapters)for(const page of chapter.pages)if(/^art\/page-[0-2]\.svg$/.test(page.url))page.url=page.url.replace('.svg','.png')}catch(e){toast('Хадгалалт боломжгүй. Хувийн горимыг шалгана уу.')}if(window.MUR_CLOUDFLARE){await refreshAccount();await syncCloudContent();}initialized=true;route()})();

captureReferral();
let selectedVipMonths=1;
let authMode=registeredHere()?'login':'register';
let accountState={signedIn:false,isAdmin:false,profile:null,vip:{active:false},xp:{balance:0},referral:null,pending:null,plan:null,loading:true,error:false};
function ageConfirmed(){return accountState.profile?.age>=18&&accountState.vip?.active===true}

function catalogList(saved=false,mature=false){return state.series.filter(s=>(mature?s.mature===true:!s.mature)&&(!saved||state.saved.includes(s.id)))}
function registrationForm(){const en=lang==='en';return `<form id="register-profile" class="form"><label>${en?'Display name':'Дэлгэцийн нэр'}<input name="displayName" required maxlength="80" autocomplete="nickname"></label><label>${en?'Date of birth':'Төрсөн он, сар, өдөр'}<input name="birthDate" type="date" min="1900-01-01" max="${new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ulaanbaatar'}).format(new Date())}" required autocomplete="bday"></label><label>${en?'Invite code · optional':'Урилгын код · заавал биш'}<input name="referralCode" value="${esc(pendingReferral())}" maxlength="32" placeholder="${en?'Added automatically from an invite link':'Урилгын холбоосоор орсон бол автоматаар бөглөгдөнө'}"></label><p class="tiny">${en?'Your age is calculated from this date. Your birth date is not shown publicly.':'Төрсөн огноогоор насыг тооцно. Төрсөн огноог бусад хэрэглэгчид харуулахгүй.'}</p><label class="check"><input name="accepted" type="checkbox" required>${en?'The date I provided is correct.':'Би төрсөн огноогоо үнэн зөв оруулсан.'}</label><button class="btn">${en?'Create profile':'Бүртгэл үүсгэх'} →</button><p id="register-error" class="form-error" role="alert"></p></form>`}
function registeredHere(){try{return localStorage.getItem('mur-registered')==='yes'}catch{return false}}
function headerAccountLabel(){const en=lang==='en';return accountState.profile?(en?'My account':'Миний бүртгэл'):registeredHere()?(en?'Sign in':'Нэвтрэх'):(en?'Register':'Бүртгүүлэх')}
function accountPanel(){if(window.MUR_CLOUDFLARE&&!accountState.loading&&!accountState.signedIn)return cloudIdentityForm();if(window.MUR_STATIC)return '<h2>Бүртгэл удахгүй</h2><p>Энэ хувилбарт уншигч, хавчуурга, уншсан байрлал ажиллана. Нэвтрэлт, админ, VIP сервер хараахан холбогдоогүй.</p>';const en=lang==='en';if(accountState.loading)return `<h2>${en?'Loading…':'Түр хүлээнэ үү…'}</h2>`;if(accountState.error)return `<h2>${en?'Connection unavailable':'Холболт тасарсан байна'}</h2><button class="btn" id="refresh-account">${en?'Retry':'Дахин шалгах'}</button>`;if(!accountState.signedIn){const login=authMode==='login';return `<div class="eyebrow">WELCOME TO Sakitoru</div><h2>${login?(en?'Welcome back':'Эргэн тавтай морил'):(en?'Create your Sakitoru account':'Sakitoru-д бүртгүүлэх')}</h2><div class="auth-tabs"><button data-auth-mode="register" class="${login?'':'selected'}">${en?'Register':'Бүртгүүлэх'}</button><button data-auth-mode="login" class="${login?'selected':''}">${en?'Sign in':'Нэвтрэх'}</button></div><p>${login?(en?'Sign in with the account you used to register.':'Өмнө бүртгүүлсэн ChatGPT хаягаараа нэвтэрнэ үү.'):(en?'Continue with ChatGPT, then add your name and date of birth.':'ChatGPT хаягаараа үргэлжлүүлээд нэр, төрсөн огноогоо оруулж бүртгүүлнэ үү.')}</p><a class="btn auth-primary" target="_top" href="/signin-with-chatgpt?return_to=%2F%23menu">${login?(en?'Sign in':'Нэвтрэх'):(en?'Continue registration':'Бүртгүүлэх')} →</a><p class="auth-switch">${login?(en?'New here?':'Бүртгэлгүй юу?'):(en?'Already registered?':'Бүртгэлтэй юу?')} <button data-auth-mode="${login?'register':'login'}">${login?(en?'Register':'Бүртгүүлэх'):(en?'Sign in':'Нэвтрэх')}</button></p>`}if(!accountState.profile)return `<div class="eyebrow">WELCOME TO Sakitoru</div><h2>${en?'Complete registration':'Бүртгүүлэх'}</h2><p>${en?'Add your details once to create your reading profile.':'Уншигчийн бүртгэлээ үүсгэхийн тулд мэдээллээ нэг удаа оруулна уу.'}</p>${registrationForm()}`;return `<div class="eyebrow">Sakitoru ACCOUNT</div><h2>${esc(accountState.profile.displayName)}</h2>${window.MUR_CLOUDFLARE?'<p class="tiny">Хэрэглэгчийн ID: '+esc(accountState.userId)+'</p>':''}<p>${en?'Declared age':'Бүртгэлд оруулсан нас'}: <b>${accountState.profile.age}</b><br>${accountState.vip.active?'VIP · '+(en?'Active until ':'Хүчинтэй: ')+vipDate(accountState.vip.expiresAt):(en?'Free membership':'Үнэгүй гишүүнчлэл')}</p><a class="btn" data-close href="#menu">${en?'Open menu':'Миний цэс'} →</a><a class="text-link" target="_top" href="#menu" data-cloud-logout>${en?'Sign out':'Гарах'}</a>`}
function maybeShowEntry(){if(window.MUR_STATIC)return;if(accountState.loading||accountState.error||accountState.profile)return;try{if(sessionStorage.getItem('mur-entry-seen'))return;sessionStorage.setItem('mur-entry-seen','yes')}catch{}auth(registeredHere()?'login':'register')}

function vipDate(n){return new Intl.DateTimeFormat(lang==='en'?'en-GB':'mn-MN',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'short',day:'numeric'}).format(new Date(n*1000))}
function vipPricing(selectable=true){const en=lang==='en',plan=accountState.plan;if(!plan?.tiers)return '';return `<div class="vip-tiers" aria-label="${en?'VIP plans':'VIP багцууд'}">${plan.tiers.map(tier=>`<button type="button" class="vip-tier ${selectedVipMonths===tier.months&&selectable?'selected':''}" data-vip-months="${tier.months}" aria-pressed="${selectable&&selectedVipMonths===tier.months}" ${selectable?'':'disabled'}><span class="tier-duration">${tier.months} ${en?'month'+(tier.months>1?'s':''):'сар'}${tier.discount?`<b>−${tier.discount}%</b>`:''}</span><strong>${tier.price.toLocaleString()}<small>₮</small></strong><span class="tier-original">${tier.discount?`<del>${tier.original.toLocaleString()}₮</del>`:(en?'Monthly plan':'Сарын эрх')}</span><span class="tier-savings">${tier.savings?(en?'Save ':'Хэмнэлт: ')+tier.savings.toLocaleString()+'₮':(en?'Standard price':'Үндсэн үнэ')}</span><span class="tier-xp">+${Number(tier.purchaseXp||0).toLocaleString()} XP</span></button>`).join('')}</div>`}
function vipPayment(){const en=lang==='en',plan=accountState.plan,pending=accountState.pending;if(pending&&plan)return `<section class="payment-instructions"><h2>${en?'Payment instructions':'Төлбөрийн мэдээлэл'}</h2><p>${en?'Request':'Захиалга'}: <b>${esc(pending.id)}</b></p><dl><div><dt>${en?'Total':'Нийт төлөх дүн'}</dt><dd>${Number(pending.price).toLocaleString()}₮</dd></div><div><dt>${en?'Duration':'Хугацаа'}</dt><dd>${pending.months||1} ${en?'months':'сар'}</dd></div><div><dt>${en?'XP after approval':'Төлбөр батлагдвал'}</dt><dd>+${Number(pending.purchase_xp||0).toLocaleString()} XP</dd></div><div><dt>${en?'Bank':'Банк'}</dt><dd>${esc(plan.bank)}</dd></div><div><dt>${en?'Account / IBAN':'Данс / IBAN'}</dt><dd>${esc(plan.account)}</dd></div><div><dt>${en?'Account name':'Хүлээн авагч'}</dt><dd>${esc(plan.account_name)}</dd></div></dl><p>${en?'Use the full request ID as the transfer description. Your VIP is activated after the payment is reviewed.':'Гүйлгээний утгад захиалгын дугаарыг бүтнээр нь бичнэ үү. Админ төлбөр орсныг шалгасны дараа VIP эрхийг нээнэ.'}</p><span class="badge">${en?'Awaiting payment review':'Төлбөр шалгахыг хүлээж байна'}</span><button class="btn secondary" id="refresh-account">${en?'Refresh status':'Эрхээ шалгах'} ↻</button></section>`;if(!plan)return `<div class="notice">${en?'Unable to load plans.':'Багцын мэдээллийг авч чадсангүй.'}</div>`;const tier=plan.tiers.find(t=>t.months===selectedVipMonths)||plan.tiers[0];return `${vipPricing()}<div class="vip-offer"><span>${tier.months} ${en?'months':'сарын эрх'} · ${en?'Total':'Нийт'}</span><strong>${tier.price.toLocaleString()}<small>₮</small></strong><p class="purchase-xp-summary">+${Number(tier.purchaseXp||0).toLocaleString()} XP · ${en?'after payment approval':'төлбөр батлагдсаны дараа'}</p>${tier.savings?`<p>${tier.discount}% ${en?'off':'хөнгөлөлт'} · ${tier.savings.toLocaleString()}₮ ${en?'saved':'хэмнэнэ'}</p>`:''}${plan.paymentReady?`<button class="btn" id="request-vip">${en?'Get payment instructions':'Төлбөрийн мэдээлэл авах'} →</button>`:`<div class="notice">${en?'Bank details have not been set yet. Orders are not available.':'Төлбөр хүлээн авах данс хараахан тохируулагдаагүй. Одоогоор захиалга авахгүй.'}</div>`}<p class="tiny">${en?'Calendar months from activation. Active memberships extend from their expiry date. No automatic renewal.':'Эрх нээгдсэн өдрөөс хуанлийн сараар тооцно. Идэвхтэй эрхийг дуусах өдрөөс нь сунгана. Автоматаар төлбөр суутгахгүй.'}</p></div>`}

function ageGate(){const en=lang==='en',underage=accountState.profile&&accountState.profile.age<18;return `<div class="container page-bottom"><section class="age-gate secret-gate"><span class="age-symbol">◈</span><div class="eyebrow">SECRET COLLECTION</div><h1>Secret</h1><span class="badge">VIP · ${en?'Age limit: 18+':'Насны хязгаар: 18+'}</span><p>${underage?(en?'Your registered age does not meet the 18+ age limit.':'Таны бүртгэлд оруулсан нас 18+ хязгаарт хүрээгүй байна.'):(en?'This collection is available to adult VIP members. Manage your account and VIP access in Menu.':'Энэ ангилал 18 нас хүрсэн VIP гишүүдэд нээлттэй. Бүртгэл болон VIP эрхээ Цэс хэсгээс удирдаарай.')}</p><a class="btn" href="#menu${underage?'':'/vip'}">${en?'Go to menu':'Цэс рүү очих'} →</a><a class="text-link secret-return" href="#home">← ${en?'Back home':'Нүүр рүү буцах'}</a></section></div>`}
function isSavedView(){return location.hash==='#menu/saved'||location.hash==='#saved'}
function menuPage(tab='overview'){const en=lang==='en',profile=accountState.profile,member=accountState.vip?.active,expired=accountState.vip?.expiresAt&&!member;const saved=catalogList(true),completed=state.series.reduce((n,s)=>n+s.chapters.filter(c=>progressFor(s.id,c.id).completed).length,0);const initial=profile?.displayName?.slice(0,1).toLocaleUpperCase()||'м';const name=profile?.displayName||(en?'Welcome, reader':'Тавтай морил');let content='';
 if(tab==='xp')content=xpHub();else if(tab==='saved')content=catalog(true);
 else if(tab==='history'){const h=state.history,s=h&&state.series.find(x=>x.id===h.series&&!x.mature);content=`<section class="panel"><h2>${en?'Reading history':'Уншсан түүх'}</h2>${s?continueBand(s):`<div class="empty">${en?'Your reading history is empty.':'Уншсан түүх одоогоор хоосон байна.'}<br><br><a class="btn" href="#catalog">${en?'Discover stories':'Бүтээл хайх'} →</a></div>`}</section>`}
 else if(tab==='vip'){let body;if(accountState.loading)body=`<p>${en?'Loading…':'Түр хүлээнэ үү…'}</p>`;else if(!profile)body=`<div class="notice">${en?'Complete your account registration before choosing VIP.':'VIP эрх авахаасаа өмнө бүртгэлээ гүйцээнэ үү.'}</div><button class="btn" data-open-account>${headerAccountLabel()} →</button>${vipPricing(false)}`;else if(profile.age<18)body=`<div class="notice">${en?'Secret VIP is available from age 18.':'Secret VIP эрхийг 18 наснаас авах боломжтой.'}</div>`;else body=vipPayment();content=`<section class="menu-vip-panel panel"><div class="eyebrow">SECRET MEMBERSHIP</div><h2>${en?'Get VIP access':'VIP эрх авах'}</h2><p class="menu-help">${en?'Choose your plan. Long-term plans include a discount.':'Багцаа сонгоорой. Урт хугацааны багц бүр хөнгөлөлттэй.'}</p><button class="xp-help-link" data-xp-guide>✦ ${en?'How does XP work?':'XP-ээр VIP эрх авах тухай'} ↗</button>${body}</section>`}
 else content=`<div class="menu-stats"><div><span>▤</span><p>${en?'Saved stories':'Хадгалсан бүтээл'}<strong>${saved.length}</strong></p></div><div><span>✓</span><p>${en?'Chapters completed':'Дуусгасан бүлэг'}<strong>${completed}</strong></p></div></div><section class="menu-vip-card"><span class="menu-crown">♛</span><div><h2>${en?'VIP membership':'VIP гишүүнчлэл'}</h2><p>${member?(en?'Active until ':'Хүчинтэй: ')+vipDate(accountState.vip.expiresAt):expired?(en?'Membership expired':'VIP эрхийн хугацаа дууссан'):(en?'No active VIP membership':'VIP эрх хараахан аваагүй байна')}</p><span class="badge">18+</span><small class="vip-no-ads">${en?'No ads while VIP is active':'VIP идэвхтэй үед заргүй'}</small></div><a class="btn" href="#menu/vip">${member?(en?'Extend VIP':'VIP сунгах'):(en?'Get VIP':'VIP эрх авах')} →</a></section>${xpMenuCard()}<div class="menu-shortcuts"><a href="#menu/saved"><span>♡</span><div><h3>${en?'Saved stories':'Хадгалсан'}</h3><p>${en?'Your personal collection':'Таны хувийн номын сан'}</p></div><b>↗</b></a><a href="#menu/history"><span>◷</span><div><h3>${en?'Reading history':'Уншсан түүх'}</h3><p>${en?'Continue your story':'Үргэлжлүүлэн унших'}</p></div><b>↗</b></a><button data-open-account><span>♙</span><div><h3>${en?'My profile':'Миний бүртгэл'}</h3><p>${en?'Account and age':'Нэр, насны мэдээлэл'}</p></div><b>↗</b></button>${accountState.isAdmin?`<a href="#admin"><span>⚙</span><div><h3>${en?'Administration':'Удирдлага'}</h3><p>${en?'Content and payments':'Бүтээл, VIP төлбөрүүд'}</p></div><b>↗</b></a>`:''}</div>`;
 return `<div class="container menu-page page-bottom"><div class="page-title"><div class="eyebrow">YOUR READING SPACE</div><h1>${en?'Menu':'Цэс'}</h1></div><section class="menu-profile"><div class="menu-banner"></div><div class="menu-profile-body"><span class="menu-avatar">${esc(initial)}</span><div><h2>${esc(name)}</h2><p>${profile?(en?'Your reading space':'Өөрийн хэмнэлээр уншаарай.'):(en?'Join Sakitoru and keep your account in one place.':'Дуртай бүтээл, VIP эрхээ эндээс удирдаарай.')}</p></div><button class="btn secondary" data-open-account>${profile?(en?'My account':'Миний бүртгэл'):headerAccountLabel()} ↗</button></div></section><nav class="menu-tabs" aria-label="${en?'Your menu':'Миний цэс'}">${[['overview',en?'Overview':'Тойм'],['saved',en?'Saved':'Сан'],['history',en?'History':'Түүх'],['vip','VIP'],['xp','XP']].map(([key,label])=>`<a href="#menu${key==='overview'?'':'/'+key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="menu-content">${content}</div>${accountState.signedIn?`<a class="menu-signout" target="_top" href="#menu" data-cloud-logout>↪ ${en?'Sign out':'Системээс гарах'}</a>`:''}</div>`}

function discoveryLinks(){return `<div class="discovery-links">${[['catalog','▤',lang==='en'?'All stories':'Бүх манхва',lang==='en'?'Find a new world':'Дараагийн түүхээ ол'],['updates','ϟ',lang==='en'?'New chapters':'Шинэ бүлгүүд',lang==='en'?'Keep the story going':'Түүхээ үргэлжлүүл'],['videos','▷',lang==='en'?'Video lounge':'Видео ертөнц',lang==='en'?'Watch and discover':'Үзээд, шинээр нээ'],['secret','◈','SECRET · VIP',lang==='en'?'18+ • Members only':'18+ • Гишүүдэд зориулсан']].map(([key,icon,name,sub])=>`<a href="#${key}" class="discovery-tile ${key}"><span>${icon}</span><div><strong>${name}</strong><small>${sub}</small></div><b>↗</b></a>`).join('')}</div>`}
async function refreshAccount(){if(window.MUR_STATIC){accountState={signedIn:false,isAdmin:false,profile:null,vip:{active:false},xp:{balance:0},loading:false,error:false};return;}try{const r=await fetch('/api/account',{cache:'no-store'}),data=await r.json();accountState={userId:data.userId,username:data.username,signedIn:r.ok&&data.signedIn===true,isAdmin:r.ok&&data.isAdmin===true,profile:data.profile||null,vip:data.vip||{active:false},xp:data.xp||{balance:0},referral:data.referral||null,pending:data.pending||null,plan:data.plan||null,loading:false,error:!r.ok&&r.status!==401};if(accountState.profile)try{localStorage.setItem('mur-registered','yes');localStorage.removeItem('mur-pending-referral')}catch{}if(accountState.vip?.active)window.MurAds?.beforeRoute();if(window.MUR_CLOUDFLARE&&initialized)await syncCloudContent()}catch{accountState={signedIn:false,profile:null,vip:{active:false},loading:false,error:true}}}
const apiMessage=code=>({invalid_referral:'Урилгын код буруу байна. Шалгаад дахин оруулах эсвэл хоосон үлдээнэ үү.',insufficient_xp:'XP хүрэлцэхгүй байна.',invalid_redemption:'Солих эрхээ дахин сонгоно уу.',redemption_conflict:'Энэ хүсэлтийн дугаар өмнө нь ашиглагдсан байна.',invalid_profile:'Нэр, төрсөн огноо болон зөвшөөрлөө шалгана уу.',profile_exists:'Бүртгэл аль хэдийн үүссэн байна.',payment_not_configured:'Төлбөрийн мэдээлэл тохируулагдаагүй.',plan_changed:'Үнэ өөрчлөгдсөн байна. Дахин шалгана уу.',age_restricted:'Насны хязгаар 18+.',admin_required:'Админы эрх шаардлагатай.',request_not_pending:'Энэ хүсэлтийг өмнө нь шийдвэрлэсэн байна.'}[code]||'Хадгалж чадсангүй. Дахин оролдоно уу.');
async function postJSON(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await r.json();if(!r.ok)throw Error(apiMessage(out.error));return out}
document.addEventListener('submit',async e=>{const f=e.target;if(!['register-profile','vip-plan'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button.btn');b.disabled=true;try{const d=new FormData(f);if(f.id==='register-profile'){await postJSON('/api/account/register',{displayName:d.get('displayName'),birthDate:d.get('birthDate'),accepted:d.get('accepted')==='on',referralCode:d.get('referralCode')||''});await refreshAccount();try{localStorage.setItem('mur-registered','yes')}catch{}$('#modal').close();route();toast(lang==='en'?'Registration complete':'Бүртгэл үүсгэлээ.')}else{await postJSON('/api/admin/vip/plan',{price:Number(d.get('price')),days:Number(d.get('days')),bank:d.get('bank'),account:d.get('account'),accountName:d.get('accountName')});await refreshAccount();route();toast('VIP үнийг хадгаллаа.')}}catch(err){const inline=f.querySelector('#register-error');if(inline)inline.textContent=err.message;else toast(err.message)}finally{b.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('#request-vip,#refresh-account,[data-vip-review]');if(!b)return;b.disabled=true;try{if(b.id==='request-vip')await postJSON('/api/vip/request',{months:selectedVipMonths,price:accountState.plan.tiers.find(t=>t.months===selectedVipMonths).price});if(b.dataset.vipReview){const approved=b.dataset.vipReview==='approve';if(approved&&!$('#payment-checked-'+b.dataset.id)?.checked)throw Error('Эхлээд банкны хуулгаас төлбөр орсныг шалгаж тэмдэглэнэ үү.');await postJSON('/api/admin/vip/review',{id:b.dataset.id,action:b.dataset.vipReview,paymentConfirmed:approved})}await refreshAccount();if($('#modal').open)$('#modal-body').innerHTML=accountPanel();route()}catch(err){toast(err.message)}finally{b.disabled=false}});
function vipAdmin(){if(accountState.loading)return '<div class="panel">Түр хүлээнэ үү…</div>';if(!accountState.isAdmin)return '<div class="panel"><h2>Админы эрх шаардлагатай</h2><p>VIP үнэ болон төлбөрийг зөвхөн сайтын эзэмшигч удирдана.</p></div>';return '<div id="vip-admin-content" class="page-bottom"><div class="panel">Төлбөрийн хүсэлтүүдийг уншиж байна…</div></div>'}
async function loadVipAdmin(){if(!accountState.isAdmin||!$('#vip-admin-content'))return;try{const r=await fetch('/api/admin/vip',{cache:'no-store'});if(!r.ok)throw Error('Төлбөрийн мэдээллийг авч чадсангүй.');const data=await r.json(),p=data.plan||{};if(!$('#vip-admin-content'))return;$('#vip-admin-content').innerHTML=`<div class="admin-layout"><section class="panel"><h2>VIP үнэ, данс тохируулах</h2><p class="tiny">3 сар −10% · 6 сар −20% · 9 сар −30% · 12 сар −40%</p><form id="vip-plan" class="form"><label>1 сарын үндсэн үнэ · ₮<input type="number" name="price" required min="1" max="10000000" step="1" value="${p.price||''}"></label><input type="hidden" name="days" value="30"><label>Банк<input name="bank" required maxlength="120" value="${esc(p.bank||'')}"></label><label>Данс / IBAN<input name="account" required maxlength="120" value="${esc(p.account||'')}"></label><label>Хүлээн авагчийн нэр<input name="accountName" required maxlength="120" value="${esc(p.account_name||'')}"></label><button class="btn">Тохиргоо хадгалах</button></form></section><section class="panel"><h2>Төлбөрийн хүсэлтүүд</h2><p class="tiny">Банкны хуулгаас дүн, захиалгын дугаарыг шалгасны дараа эрхийг нээнэ.</p>${data.requests.length?data.requests.map(r=>`<article class="vip-request"><strong>${esc(r.display_name||'Хэрэглэгч')}</strong><small class="request-id">${esc(r.id)}</small><p>${r.price.toLocaleString()}₮ · ${r.months||1} сар · +${Number(r.purchase_xp||0).toLocaleString()} XP · ${vipDate(r.created_at)}</p>${r.status==='pending'?`<label class="check"><input id="payment-checked-${r.id}" type="checkbox">Банкны хуулгаас төлбөр орсныг шалгасан</label><div class="vip-review"><button class="btn" data-vip-review="approve" data-id="${r.id}">VIP нээх</button><button class="btn secondary" data-vip-review="reject" data-id="${r.id}">Татгалзах</button></div>`:`<span class="badge">${r.status==='approved'?'Эрх нээсэн':'Татгалзсан'}</span>`}</article>`).join(''):'<div class="notice">Төлбөрийн хүсэлт хараахан ирээгүй.</div>'}</section></div>`}catch(err){if($('#vip-admin-content'))$('#vip-admin-content').textContent=err.message}}
if(!window.MUR_CLOUDFLARE)refreshAccount().then(()=>{route();maybeShowEntry()});

document.addEventListener('click',e=>{const b=e.target.closest('[data-vip-months]');if(!b||b.disabled)return;selectedVipMonths=Number(b.dataset.vipMonths);route()});

document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]');if(mode){auth(mode.dataset.authMode);return}if(e.target.closest('[data-open-account]'))auth()});

function xpMenuCard(){const en=lang==='en';return `<section class="xp-menu-card"><span class="xp-emblem" aria-hidden="true">✦</span><div class="xp-card-copy"><span class="xp-kicker">${en?'READER REWARDS':'УНШИГЧИЙН УРАМШУУЛАЛ'}</span><h2>${en?'Earn XP with VIP':'VIP аваад XP цуглуулаарай'}</h2><p>${en?'Earn XP with purchases and referrals, then exchange it for VIP.':'VIP аваад, найзаа уриад XP цуглуул. Оноогоо VIP эрхээр солиорой.'}</p>${accountState.profile?`<div class="xp-balance"><span>${en?'Your balance':'Таны XP үлдэгдэл'}</span><strong>${Number(accountState.xp?.balance||0).toLocaleString()} XP</strong></div>`:''}<span class="xp-example-tag">${en?'Example: 1,000 XP → 3 days of VIP':'Жишээ: 1,000 XP → 3 хоног VIP'}</span></div><button class="btn secondary" data-xp-guide>${en?'How it works':'Хэрхэн ашиглах вэ?'} ↗</button><a class="xp-use-link" href="#menu/xp">${en?'My XP & invite link':'Миний XP · Найзаа урих'} →</a><small class="xp-card-status">${en?'Paid referrals earn XP once, after payment approval.':'Найзын анхны VIP төлбөр батлагдвал урьсан хүнд 1,000 XP.'}</small></section>`}
function xpGuide(){const en=lang==='en';return `<section class="xp-guide"><span class="xp-guide-icon" aria-hidden="true">✦</span><div class="eyebrow">Sakitoru REWARDS</div><h2>${en?'XP rewards, explained':'XP урамшууллыг хэрхэн ашиглах вэ?'}</h2><p class="xp-intro">${en?'XP is a reward point you can exchange for VIP reading time. It cannot be withdrawn as money.':'XP бол VIP эрхээр сольж ашиглах урамшууллын оноо юм. Мөнгө болгон авах боломжгүй.'}</p><div class="xp-preview-notice" role="note">${en?'Purchase XP, paid-referral rewards and VIP exchanges are available in Menu → XP. The calculations below are examples, not your personal balance.':'Худалдан авалтын XP, найзын урилгын оноо, VIP эрхээр солих боломжийг Цэс → XP хэсгээс ашиглана. Доорх тоонууд нь таны үлдэгдэл биш, жишээ тооцоо юм.'}</div>${purchaseXpGuide()}<h3>${en?'2. Earn XP by inviting a friend':'2. Найзаа уриад XP цуглуулах'}</h3><ol class="xp-steps"><li>${en?'Sign in, then share your personal invite link with a friend.':'Өөрийн бүртгэлээр нэвтэрч, хувийн урилгын холбоосоо найздаа илгээнэ.'}</li><li>${en?'Your friend registers through that link and makes their first paid VIP purchase. Any plan earns a one-time 1,000 XP reward.':'Найз тань холбоосоор бүртгүүлээд, анхны төлбөртэй VIP эрхээ авна. Аль ч багцад нэг удаа 1,000 XP олгоно.'}</li><li>${en?'After payment is confirmed, you receive 1,000 XP.':'Төлбөр баталгаажсаны дараа танд 1,000 XP нэмэгдэнэ.'}</li></ol><div class="xp-simple-example"><span>${en?'One friend’s first 5,000₮ VIP purchase':'Найзын анхны 5,000₮-ийн VIP төлбөр'}</span><strong>+1,000 XP</strong><small>${en?'A registration alone does not earn this paid-referral reward.':'Зөвхөн бүртгүүлснээр энэ төлбөртэй урилгын оноо нэмэгдэхгүй.'}</small></div><h3>${en?'3. Exchange XP for VIP':'3. XP-гээ VIP эрхээр солих'}</h3><table class="xp-reward-table"><thead><tr><th>${en?'Points needed':'Солих оноо'}</th><th>${en?'VIP access':'Авах эрх'}</th></tr></thead><tbody><tr><td>1,000 XP</td><td>${en?'3 days':'3 хоног'}</td></tr><tr><td>2,300 XP</td><td>${en?'7 days':'7 хоног'}</td></tr><tr><td>10,000 XP</td><td>${en?'1 month':'1 сар'}</td></tr></tbody></table><p>${en?'Choose a reward in Menu → XP, then confirm. The points are deducted and VIP is activated. Existing VIP extends from its expiry.':'Цэс → XP хэсгээс эрхээ сонгоод батална. Оноо хасагдаж, VIP эрх шууд нээгдэнэ. Одоо VIP эрхтэй бол дуусах өдрөөс нь сунгана.'}</p><h3>${en?'4. Try a referral example':'4. Урилгын жишээгээр ойлгоё'}</h3><div class="xp-calculator"><label for="xp-example-count">${en?'Friends whose first 5,000₮ VIP payment is confirmed':'Анхны 5,000₮-ийн VIP төлбөр нь баталгаажсан найзын тоо'}</label><select id="xp-example-count"><option value="1">1 ${en?'friend':'найз'}</option><option value="3">3 ${en?'friends':'найз'}</option><option value="10">10 ${en?'friends':'найз'}</option></select><div id="xp-example-result" aria-live="polite">${xpExample(1)}</div><small>${en?'Example only · No XP is awarded by this calculator.':'Зөвхөн жишээ · Энд сонголт хийхэд XP нэмэгдэхгүй.'}</small></div><div class="xp-guide-rules"><h3>${en?'Remember':'Санах зүйлс'}</h3><ul><li>${en?'Secret access still requires age 18 or older.':'Secret хэсэгт 18+ насны нөхцөл хэвээр үйлчилнэ.'}</li><li>${en?'Self-invites and duplicate accounts do not qualify.':'Өөрийгөө урих, давхар бүртгэл үүсгэхэд урамшуулал олгохгүй.'}</li><li>${en?'Points are only awarded after approval, once per payment.':'XP-г батлагдсан төлбөр бүрд нэг удаа олгоно. Төлбөрийн хүсэлт үүсгэхэд шууд нэмэгдэхгүй.'}</li></ul></div><button class="btn xp-guide-close" data-close>${en?'Got it':'Ойлголоо'} ✓</button></section>`}
function xpExample(count){const en=lang==='en',n=[1,3,10].includes(Number(count))?Number(count):1,points=n*1000,cost=n===10?10000:n===3?2300:1000;return `<span>${n} ${en?'paid referrals':'найз'} × 1,000 XP</span><strong>${points.toLocaleString()} XP</strong><p>${en?'You could exchange':'Солих боломжтой эрх'}: <b>${n===10?(en?'1 month VIP':'1 сарын VIP'):n===3?(en?'7 days VIP':'7 хоногийн VIP'):(en?'3 days VIP':'3 хоногийн VIP')}</b></p><p>${en?'After this exchange':'Сольсны дараах үлдэгдэл'}: <b>${(points-cost).toLocaleString()} XP</b></p>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-xp-guide]'))modal(xpGuide())});
document.addEventListener('change',e=>{if(e.target.id==='xp-example-count'&&$('#xp-example-result'))$('#xp-example-result').innerHTML=xpExample(e.target.value)});

function purchaseXpGuide(){const en=lang==='en',tiers=accountState.plan?.tiers||[{months:1,price:5000,xpRate:10,purchaseXp:500},{months:3,price:13500,xpRate:8,purchaseXp:1080},{months:6,price:24000,xpRate:6,purchaseXp:1440},{months:9,price:31500,xpRate:5,purchaseXp:1575},{months:12,price:36000,xpRate:5,purchaseXp:1800}];return `<h3>${en?'1. Earn XP from your VIP purchase':'1. Өөрөө VIP аваад XP цуглуулах'}</h3><p>${en?'XP is calculated from the discounted amount you actually pay. Higher-discount plans earn at a lower rate.':'XP-г хөнгөлөлт тооцсон, бодитоор төлсөн дүнгээс бодно. Хөнгөлөлттэй багцад бага хувиар XP олгоно.'}</p><div class="xp-purchase-table-wrap"><table class="xp-reward-table xp-purchase-table"><thead><tr><th>${en?'Plan':'Багц'}</th><th>${en?'Payment':'Төлөх дүн'}</th><th>${en?'XP rate':'XP хувь'}</th><th>${en?'Earn':'Авах XP'}</th></tr></thead><tbody>${tiers.map(t=>`<tr><td>${t.months} ${en?'mo':'сар'}</td><td>${t.price.toLocaleString()}₮</td><td>${t.xpRate}%</td><td>+${t.purchaseXp.toLocaleString()}</td></tr>`).join('')}</tbody></table></div><div class="xp-simple-example"><span>${en?'Example: one-month VIP':'Жишээ: 1 сарын VIP'}</span><strong>5,000 × 10% = 500 XP</strong><small>${en?'These percentages calculate reward points, not extra money off. XP is added once, after payment approval.':'Энэ хувь нь авах оноог тооцох хувь юм. Төлөх мөнгөнөөс дахин хасахгүй. Төлбөр батлагдахад 500 XP нэг удаа нэмэгдэнэ.'}</small></div>`}

function adsAdmin(){if(!accountState.isAdmin)return '<div class="panel"><h2>Админы эрх шаардлагатай</h2></div>';return '<section id="ads-admin" class="panel page-bottom">Зарын тохиргоог уншиж байна…</section>'}
async function loadAdsAdmin(){if(!accountState.isAdmin||!$('#ads-admin'))return;try{const r=await fetch('/api/admin/ads',{cache:'no-store'});if(!r.ok)throw Error();const {settings:s}=await r.json(),c=s||{};if(!$('#ads-admin'))return;$('#ads-admin').innerHTML=`<div class="eyebrow">ADVERTISING</div><h2>Зарын орлого</h2><p class="notice">Google Ad Manager-ийн батлагдсан зарын нэгжийг холбоно. Код холбогдоогүй үед хэрэглэгчид зар, хуурамч тоолуур харуулахгүй. Орлогыг зарын үйлчилгээний тайлангаас харна.</p><div class="ads-placement-list"><div><strong>Нүүр, манхва, видео</strong><span>Хуудасны доторх зарын байрлал</span></div><div><strong>5 өөр бүлэг дуусгасны дараа</strong><span>Бүлгийн төгсгөлд зарын байрлал</span></div><div><strong>Бүтэн дэлгэцийн зар</strong><span>Үйлчилгээ дэмжсэн шилжилтэд; хугацаа, хаах товчийг Google удирдана</span></div><div><strong>Давтамж</strong><span>Бүтэн дэлгэцийн зарын хүсэлт хооронд дор хаяж 10 минут</span></div></div><form id="ad-settings" class="form"><label>Хуудасны доторх зарын Ad unit path<input name="displayUnit" value="${esc(c.display_unit||'')}" placeholder="/сүлжээний-дугаар/зарын-нэгж" maxlength="185"></label><label>Бүтэн дэлгэцийн зарын Ad unit path · сонголтоор<input name="interstitialUnit" value="${esc(c.interstitial_unit||'')}" placeholder="/сүлжээний-дугаар/зарын-нэгж" maxlength="185"></label><label class="check"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}> Бодит зарын хүсэлт илгээхийг идэвхжүүлэх</label><label class="check"><input type="checkbox" name="confirmed"> Миний зарын бүртгэл болон энэ сайтад ашиглах зарын нэгж батлагдсан.</label><p class="tiny">Үндсэн бүтээлүүд дээр зар харуулна. Secret, бүртгэл, төлбөр, админ болон идэвхтэй VIP хэрэглэгчийн хуудсанд зар хүсэхгүй. Сайтын одоогийн хандалтын тохиргоо өөрчлөгдөхгүй.</p><button class="btn">Тохиргоо хадгалах</button></form>`}catch{if($('#ads-admin'))$('#ads-admin').textContent='Зарын тохиргоог авч чадсангүй.'}}
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='ad-settings')return;e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const d=new FormData(f);await postJSON('/api/admin/ads',{enabled:d.get('enabled')==='on',displayUnit:d.get('displayUnit').trim(),interstitialUnit:d.get('interstitialUnit').trim(),confirmed:d.get('confirmed')==='on'});toast('Зарын тохиргоог хадгаллаа.');window.MurAds?.reloadConfig()}catch(err){toast(err.message)}finally{b.disabled=false}});

function captureReferral(){try{const code=new URLSearchParams(location.search).get('ref');if(code&&/^[a-f0-9]{32}$/.test(code))localStorage.setItem('mur-pending-referral',JSON.stringify({code,created:Date.now()}))}catch{}}
function pendingReferral(){try{const r=JSON.parse(localStorage.getItem('mur-pending-referral')||'null');return r&&Date.now()-r.created<30*86400000&&/^[a-f0-9]{32}$/.test(r.code)?r.code:''}catch{return ''}}
const xpRewards=[{key:'vip3',cost:1000,mn:'3 хоног VIP',en:'3 days VIP'},{key:'vip7',cost:2300,mn:'7 хоног VIP',en:'7 days VIP'},{key:'vipMonth',cost:10000,mn:'1 сар VIP',en:'1 month VIP'}];
function inviteUrl(){return accountState.referral?.code?location.origin+'/?ref='+accountState.referral.code:''}
function xpHub(){const en=lang==='en',p=accountState.profile,balance=Number(accountState.xp?.balance||0),r=accountState.referral;return `<section class="xp-hub panel"><div class="eyebrow">Sakitoru REWARDS</div><h2>${en?'My XP':'Миний XP'}</h2>${!p?`<div class="notice">${en?'Sign in and complete your profile to use XP.':'XP ашиглахын тулд бүртгэлээрээ нэвтэрнэ үү.'}</div><button class="btn" data-open-account>${headerAccountLabel()} →</button>`:`<div class="xp-wallet"><span>${en?'Available balance':'Ашиглах боломжтой оноо'}</span><strong>${balance.toLocaleString()} XP</strong><small>${en?'Points are saved to your account.':'Оноо таны бүртгэлд хадгалагдана.'}</small></div><button id="refresh-account" class="xp-help-link">↻ ${en?'Refresh points':'Оноогоо шинэчлэх'}</button><h3>${en?'Invite a friend':'Найзаа урих'}</h3><p>${en?'Your friend’s first approved paid VIP purchase earns you 1,000 XP, once.':'Найзын анхны төлбөртэй VIP батлагдвал танд нэг удаа 1,000 XP нэмэгдэнэ.'}</p>${r?`<label class="invite-field">${en?'Your invite link':'Таны урилгын холбоос'}<input id="invite-link" readonly value="${esc(inviteUrl())}"></label><button class="btn secondary" id="copy-invite">${en?'Copy link':'Холбоос хуулах'} ⧉</button><div class="invite-stats"><span>${en?'Registered friends':'Бүртгүүлсэн найз'} <b>${r.registered}</b></span><span>${en?'Rewarded referrals':'Оноо авсан урилга'} <b>${r.rewarded}</b></span></div>`:''}<h3>${en?'Exchange XP for VIP':'Оноогоо VIP эрхээр солих'}</h3>${p.age<18?`<div class="notice">${en?'Secret VIP requires age 18 or older. You can keep your XP balance.':'Secret VIP эрхийг 18 наснаас авна. Цуглуулсан XP тань хадгалагдана.'}</div>`:''}<div class="xp-redemption-grid">${xpRewards.map(reward=>`<article><span>VIP · 18+</span><h4>${en?reward.en:reward.mn}</h4><strong>${reward.cost.toLocaleString()} XP</strong><button class="btn" data-confirm-xp="${reward.key}" ${balance<reward.cost||p.age<18?'disabled':''}>${balance<reward.cost?(en?'Need more XP':'XP хүрэлцэхгүй'):(en?'Exchange':'Эрх авах')} →</button></article>`).join('')}</div><p class="tiny">${en?'Points are deducted after confirmation. This exchange does not award purchase or referral XP.':'Батлахад оноо хасагдана. XP-ээр авсан эрхэд худалдан авалтын болон урилгын оноо дахин олгохгүй.'}</p>`}<button class="xp-help-link" data-xp-guide>${en?'How to use XP':'XP ашиглах заавар'} ↗</button></section>`}
document.addEventListener('click',async e=>{const copy=e.target.closest('#copy-invite');if(copy){try{await navigator.clipboard.writeText(inviteUrl());toast(lang==='en'?'Invite link copied':'Урилгын холбоос хууллаа.')}catch{toast(lang==='en'?'Select and copy the link above.':'Дээрх холбоосыг сонгоод хуулна уу.')}return}const confirm=e.target.closest('[data-confirm-xp]');if(confirm){const reward=xpRewards.find(r=>r.key===confirm.dataset.confirmXp);if(!reward)return;const en=lang==='en';modal(`<div class="eyebrow">XP EXCHANGE</div><h2>${en?reward.en:reward.mn}</h2><p>${reward.cost.toLocaleString()} XP ${en?'will be deducted. Your VIP starts now, or extends your current membership.':'хасагдана. VIP эрх нээгдэж, идэвхтэй эрхтэй бол хугацаа нь сунгагдана.'}</p><button class="btn" data-redeem-xp="${reward.key}" data-request-id="${crypto.randomUUID()}">${en?'Confirm exchange':'Баталж эрх авах'} →</button> <button class="btn secondary" data-close>${en?'Cancel':'Болих'}</button>`);return}const redeem=e.target.closest('[data-redeem-xp]');if(redeem){redeem.disabled=true;try{await postJSON('/api/xp/redeem',{reward:redeem.dataset.redeemXp,requestId:redeem.dataset.requestId});await refreshAccount();$('#modal').close();route();toast(lang==='en'?'VIP activated with XP':'XP-ээр VIP эрхээ нээлээ.')}catch(err){toast(err.message);redeem.disabled=false}}});
async function syncMembership(){if(accountState.loading||!accountState.signedIn||(!accountState.pending&&!accountState.vip?.active))return;const previous=accountState.vip?.active;await refreshAccount();if(previous!==accountState.vip?.active){captureReaderPosition();route()}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncMembership()});
if(typeof window.setInterval==='function')window.setInterval(()=>{if(document.visibilityState==='visible')syncMembership()},60000);

function canManage(){return typeof accountState!=='undefined'&&!accountState.loading&&accountState.isAdmin===true}
function sameContent(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b))return false;const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(k=>Object.prototype.hasOwnProperty.call(b,k)&&sameContent(a[k],b[k]))}
function ownerOnlyPage(){const en=lang==='en';return `<div class="container page-bottom"><section class="owner-only panel"><span class="owner-lock" aria-hidden="true">♜</span><div class="eyebrow">OWNER WORKSPACE</div><h1>${accountState.loading?(en?'Checking access…':'Хандах эрхийг шалгаж байна…'):(en?'Owner access only':'Зөвхөн сайтын эзэмшигчид')}</h1><p>${en?'Only the site owner can add stories, manage chapters or approve VIP payments. Your reader account can read, save stories and use XP.':'Бүтээл нэмэх, бүлэг удирдах, VIP төлбөр батлах хэсгийг зөвхөн эзэмшигч ашиглана. Та манхва унших, хадгалах болон XP ашиглах боломжтой.'}</p><a class="btn" href="#menu">${en?'Back to menu':'Цэс рүү буцах'} →</a>${!accountState.loading&&!accountState.signedIn?`<button class="btn secondary" data-open-account>${en?'Owner sign in':'Эзэмшигчээр нэвтрэх'}</button>`:''}</section></div>`}
function syncAdminLinks(){document.querySelectorAll('a[href^="#admin"],[data-admin-only]').forEach(link=>{link.hidden=!canManage()})}
// Capture before any form or mutation handler. Server APIs independently enforce ownership.
document.addEventListener('submit',e=>{if(['add-series','add-chapter','translate','edit-series','append-pages','add-video','vip-plan','ad-settings'].includes(e.target.id)&&!canManage()){e.preventDefault();e.stopImmediatePropagation();toast('Энэ үйлдлийг зөвхөн сайтын эзэмшигч хийнэ.')}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||canManage())return;const attributes=['deleteSeries','deleteChapter','confirmDelete','move','editSeries','pageMove','pageRemove','deleteVideo','confirmVideoDelete','vipReview'];if(attributes.some(key=>Object.prototype.hasOwnProperty.call(b.dataset,key))||['undo-edit','undo-restoration','confirm-restore','add-region','remove-region','undo-region','export-library'].includes(b.id)){e.preventDefault();e.stopImmediatePropagation();toast('Энэ үйлдлийг зөвхөн сайтын эзэмшигч хийнэ.')}},true);
document.addEventListener('change',e=>{if(e.target.id==='restore-backup'&&!canManage()){e.preventDefault();e.stopImmediatePropagation();e.target.value='';toast('Нөөц сэргээх эрх зөвхөн эзэмшигчид байна.')}},true);
